// ---- Koi Glide (snake) ----
Games.koi = function () {
  const el = document.getElementById("koi"); if (!el) return;
  const C = 16, R = 20, S = 20; let snake, dir, nxt, food, acc, last;
  const place = () => { let p; do p = { x: Math.floor(Math.random() * C), y: Math.floor(Math.random() * R) }; while (snake.some((s) => s.x === p.x && s.y === p.y)); return p; };
  const api = this.canvasGame(el, { title: "koi", help: "Swipe or use arrow keys. Eat the petals; avoid the bank and your tail.",
    onStart() { snake = [{ x: 8, y: 10 }, { x: 7, y: 10 }, { x: 6, y: 10 }]; dir = nxt = { x: 1, y: 0 }; food = place(); acc = 0; last = 0; },
    draw(a, t) { const { g, W, H } = a; const dt = Math.min(100, (t - last) || 16); last = t; acc += dt; const ms = Math.max(65, 150 - a.score * 3);
      while (acc >= ms) { acc -= ms; dir = nxt; const h = { x: snake[0].x + dir.x, y: snake[0].y + dir.y };
        if (h.x < 0 || h.y < 0 || h.x >= C || h.y >= R || snake.some((s) => s.x === h.x && s.y === h.y)) return a.over("The koi struck the bank");
        snake.unshift(h); if (h.x === food.x && h.y === food.y) { a.set(a.score + 1); food = place(); } else snake.pop(); }
      const grd = g.createLinearGradient(0, 0, 0, H); grd.addColorStop(0, "#0e2230"); grd.addColorStop(1, "#0a141c"); g.fillStyle = grd; g.fillRect(0, 0, W, H);
      g.strokeStyle = "rgba(255,255,255,.04)"; for (let i = 0; i <= C; i++) { g.beginPath(); g.moveTo(i * S, 0); g.lineTo(i * S, H); g.stroke(); } for (let j = 0; j <= R; j++) { g.beginPath(); g.moveTo(0, j * S); g.lineTo(W, j * S); g.stroke(); }
      g.font = "18px serif"; g.textAlign = "center"; g.textBaseline = "middle"; g.fillText("🌸", food.x * S + S / 2, food.y * S + S / 2 + 1);
      snake.forEach((s, i) => { const k = 1 - i / (snake.length + 2); g.fillStyle = i % 3 === 1 ? `rgba(255,248,235,${0.5 + k * 0.5})` : `rgba(255,${Math.round(110 + 40 * k)},58,${0.55 + k * 0.45})`;
        g.beginPath(); g.arc(s.x * S + S / 2, s.y * S + S / 2, S / 2 - 1 - (i / snake.length) * 3, 0, 7); g.fill(); });
      const h = snake[0]; g.fillStyle = "#fff"; [[-4, -4], [4, -4]].forEach(([dx, dy]) => { g.beginPath(); g.arc(h.x * S + S / 2 + dx * (dir.y ? 1 : 0.4) + (dir.x ? dir.x * 3 : 0), h.y * S + S / 2 + dy * (dir.x ? 1 : 0.4) + (dir.y ? dir.y * 3 : 0), 2.2, 0, 7); g.fill(); }); } });
  const turn = (x, y) => { if (x === -dir.x && y === -dir.y) return; nxt = { x, y }; };
  keyGuard("koi", (e) => { const m = { ArrowUp: [0, -1], ArrowDown: [0, 1], ArrowLeft: [-1, 0], ArrowRight: [1, 0], w: [0, -1], s: [0, 1], a: [-1, 0], d: [1, 0] }[e.key]; if (m && api.run) { e.preventDefault(); turn(...m); } });
  let sx, sy; api.cv.addEventListener("pointerdown", (e) => { sx = e.clientX; sy = e.clientY; });
  api.cv.addEventListener("pointermove", (e) => { if (sx == null || !api.run) return; const dx = e.clientX - sx, dy = e.clientY - sy; if (Math.hypot(dx, dy) < 18) return; if (Math.abs(dx) > Math.abs(dy)) turn(Math.sign(dx), 0); else turn(0, Math.sign(dy)); sx = e.clientX; sy = e.clientY; });
  api.cv.addEventListener("pointerup", () => (sx = null));
};

// ---- Ink Clash (Stroop) ----
Games.ink = function () {
  const el = document.getElementById("ink"); if (!el) return;
  const COLS = [["RED", "#e0452f"], ["BLUE", "#4a90c2"], ["GREEN", "#46aa6e"], ["GOLD", "#d9a53b"]]; let score, left, timer, ink;
  const show = () => { const w = COLS[Math.floor(Math.random() * 4)]; ink = Math.random() < 0.75 ? COLS[(COLS.indexOf(w) + 1 + Math.floor(Math.random() * 3)) % 4] : w;
    el.querySelector(".ik-w").textContent = w[0]; el.querySelector(".ik-w").style.color = ink[1]; };
  const intro = () => { clearInterval(timer); el.innerHTML = `<div class="game-stats"><span>Best <b>${Games.best("ink")}</b></span></div><div class="cv-over static"><b>30 seconds. Tap the colour of the INK, not the word.</b><button class="btn btn-primary" type="button">Start</button></div>`; el.querySelector("button").onclick = start; };
  const start = () => { score = 0; left = 30;
    el.innerHTML = `<div class="game-stats"><span>Score <b class="ik-s">0</b></span><span>Time <b class="ik-t">30</b>s</span><span>Best <b>${Games.best("ink")}</b></span></div><div class="ik-w"></div><div class="sp-bar"><u></u></div>
      <div class="sp-o">${COLS.map((c) => `<button type="button" class="sp-btn ik-b" data-n="${c[0]}">${c[0]}</button>`).join("")}</div>`;
    show(); el.querySelectorAll(".ik-b").forEach((b) => (b.onclick = () => { if (b.dataset.n === ink[0]) score++; else score = Math.max(0, score - 1); el.querySelector(".ik-s").textContent = score; show(); }));
    timer = setInterval(() => { left--; el.querySelector(".ik-t") && (el.querySelector(".ik-t").textContent = left); el.querySelector(".sp-bar u") && (el.querySelector(".sp-bar u").style.width = (left / 30) * 100 + "%");
      if (left <= 0) { clearInterval(timer); if (score > Games.best("ink")) Games.setBest("ink", score); el.innerHTML = `<div class="cv-over static"><b>Time! Score ${score}</b><button class="btn btn-primary" type="button">Again</button></div>`; el.querySelector("button").onclick = start; } }, 1000);
    (Games.ivs = Games.ivs || []).push(timer); };
  intro();
};

// ---- Taiko Echo (Simon) ----
Games.taiko = function () {
  const el = document.getElementById("taiko"); if (!el) return;
  const PADS = ["#d9362b", "#d9a53b", "#2f8f82", "#4262b0"], F = [262, 330, 392, 523]; let seq, pos, lock, ac;
  const tone = (i) => { try { ac = ac || new (window.AudioContext || window.webkitAudioContext)(); const o = ac.createOscillator(), g = ac.createGain(); o.frequency.value = F[i]; o.type = "triangle"; g.gain.setValueAtTime(0.18, ac.currentTime); g.gain.exponentialRampToValueAtTime(0.001, ac.currentTime + 0.35); o.connect(g); g.connect(ac.destination); o.start(); o.stop(ac.currentTime + 0.36); } catch {} };
  const sleep = (ms) => new Promise((r) => Games.timers.push(setTimeout(r, ms)));
  const pad = (i) => el.querySelector(`.tk-pad[data-i="${i}"]`);
  const flash = async (i) => { const p = pad(i); if (!p) return; p.classList.add("lit"); tone(i); await sleep(380); p.classList.remove("lit"); };
  const play = async () => { lock = true; el.querySelector(".tk-msg").textContent = "Watch…"; await sleep(600); for (const i of seq) { await flash(i); await sleep(170); } lock = false; pos = 0; el.querySelector(".tk-msg").textContent = "Your turn"; };
  const next = () => { seq.push(Math.floor(Math.random() * 4)); el.querySelector(".tk-r").textContent = seq.length - 1; play(); };
  const over = () => { const sc = seq.length - 1; if (sc > Games.best("taiko")) Games.setBest("taiko", sc); el.innerHTML = `<div class="cv-over static"><b>You reached round ${sc}</b><button class="btn btn-primary" type="button">Again</button></div>`; el.querySelector("button").onclick = start; };
  const start = () => { seq = []; pos = 0; lock = true;
    el.innerHTML = `<div class="game-stats"><span>Round <b class="tk-r">0</b></span><span class="tk-msg">Watch…</span><span>Best <b>${Games.best("taiko")}</b></span></div><div class="tk-grid">${PADS.map((c, i) => `<button type="button" class="tk-pad" data-i="${i}" style="--c:${c}" aria-label="Drum ${i + 1}"></button>`).join("")}</div>`;
    el.querySelectorAll(".tk-pad").forEach((b) => (b.onclick = async () => { if (lock) return; const i = Number(b.dataset.i); flash(i); if (i !== seq[pos]) return over(); pos++; if (pos === seq.length) { lock = true; await sleep(550); next(); } }));
    next(); };
  el.innerHTML = `<div class="game-stats"><span>Best <b>${Games.best("taiko")}</b></span></div><div class="cv-over static"><b>Repeat the drum pattern. It grows every round.</b><button class="btn btn-primary" type="button">Start</button></div>`; el.querySelector("button").onclick = start;
};

// ---- Word Forge (anagrams) ----
Games.words = function () {
  const el = document.getElementById("words"); if (!el) return;
  const W = [["JUDGE", "Presides over a court"], ["VERDICT", "The decision reached by a jury"], ["STATUTE", "A written law made by a legislature"], ["APPEAL", "Ask a higher court to review a decision"], ["TRIBUNAL", "A body set up to settle particular disputes"], ["ADVOCATE", "A lawyer who pleads in court"],
    ["PRECEDENT", "An earlier case that guides later ones"], ["CONTRACT", "A legally binding agreement"], ["TESTIMONY", "A witness's statement under oath"], ["PLAINTIFF", "The person who brings a case"], ["DEFENDANT", "The person accused or sued"], ["WARRANT", "A document authorising an arrest or search"],
    ["EVIDENCE", "Facts presented to prove a case"], ["AMENDMENT", "A change made to the Constitution"], ["PREAMBLE", "The introduction to the Constitution"], ["SOVEREIGN", "Having supreme power"], ["REPUBLIC", "A state headed by an elected president"], ["BALLOT", "A vote cast in secret"], ["PARLIAMENT", "The legislature of India"], ["JUSTICE", "Fairness under the law"]];
  let list, i, score, built, tiles;
  const scramble = (w) => { let s; do s = shuf(w.split("")).join(""); while (s === w); return s; };
  const draw = () => { if (i >= 8) { if (score > Games.best("words")) Games.setBest("words", score); el.innerHTML = `<div class="cv-over static"><b>${score} / 8 solved${score === 8 ? " · flawless 🏆" : ""}</b><button class="btn btn-primary" type="button">Again</button></div>`; return (el.querySelector("button").onclick = start); }
    const [w, hint] = list[i]; if (!tiles) tiles = scramble(w).split(""); const used = built.map((b) => b.t);
    el.innerHTML = `<div class="game-stats"><span>Word <b>${i + 1}</b>/8</span><span>Score <b>${score}</b></span><span>Best <b>${Games.best("words")}</b></span></div>
      <p class="wf-hint">${hint}</p><div class="wf-ans">${w.split("").map((_, k) => `<span class="${built[k] ? "on" : ""}">${built[k] ? built[k].c : ""}</span>`).join("")}</div>
      <div class="wf-tiles">${tiles.map((c, t) => `<button type="button" class="wf-t" data-t="${t}" ${used.includes(t) ? "disabled" : ""}>${c}</button>`).join("")}</div>
      <div class="wf-ctl"><button type="button" class="btn btn-ghost" id="wf-undo">Undo</button><button type="button" class="btn btn-ghost" id="wf-shuf">Shuffle</button><button type="button" class="btn btn-ghost" id="wf-skip">Skip</button></div>`;
    el.querySelectorAll(".wf-t").forEach((b) => (b.onclick = () => { built.push({ t: Number(b.dataset.t), c: tiles[b.dataset.t] }); if (built.length === w.length) { if (built.map((x) => x.c).join("") === w) { score++; el.querySelector(".wf-ans").classList.add("ok"); setTimeout(() => { i++; built = []; tiles = null; draw(); }, 650); } else { el.querySelector(".wf-ans").classList.add("bad"); setTimeout(() => { built = []; draw(); }, 600); } } else draw(); }));
    el.querySelector("#wf-undo").onclick = () => { built.pop(); draw(); }; el.querySelector("#wf-shuf").onclick = () => { tiles = shuf(tiles); built = []; draw(); }; el.querySelector("#wf-skip").onclick = () => { i++; built = []; tiles = null; draw(); }; };
  const start = () => { list = shuf(W).slice(0, 8); i = 0; score = 0; built = []; tiles = null; draw(); };
  el.innerHTML = `<div class="game-stats"><span>Best <b>${Games.best("words")}</b></span></div><div class="cv-over static"><b>Eight scrambled words, one hint each.</b><button class="btn btn-primary" type="button">Start</button></div>`; el.querySelector("button").onclick = start;
};

// ---- Constitution Quiz ----
Games.consti = function () {
  const el = document.getElementById("consti"); if (!el) return;
  const Q = [["Who chaired the Drafting Committee of the Constitution?", ["B. R. Ambedkar", "Jawaharlal Nehru", "Rajendra Prasad"], "Dr B. R. Ambedkar chaired the Drafting Committee."], ["Which Article abolishes untouchability?", ["Article 17", "Article 15", "Article 21"], "Article 17 abolishes untouchability and forbids its practice."],
    ["Right to Life and Personal Liberty is in…", ["Article 21", "Article 19", "Article 32"], "Article 21 protects life and personal liberty."], ["Which Article gives the Right to Constitutional Remedies?", ["Article 32", "Article 14", "Article 226"], "Article 32 lets you move the Supreme Court for enforcement of Fundamental Rights."],
    ["Fundamental Rights are in which Part of the Constitution?", ["Part III", "Part IV", "Part II"], "Part III holds the Fundamental Rights; Part IV the Directive Principles."], ["The Constitution came into force on…", ["26 January 1950", "15 August 1947", "26 November 1949"], "It was adopted on 26 Nov 1949 and came into force on 26 Jan 1950."],
    ["Which Amendment added the Fundamental Duties?", ["42nd", "44th", "73rd"], "The 42nd Amendment (1976) added Fundamental Duties."], ["Right to Education is under which Article?", ["Article 21A", "Article 45", "Article 19"], "Article 21A, added by the 86th Amendment."], ["Equality before the law is guaranteed by…", ["Article 14", "Article 16", "Article 25"], "Article 14: equality before law and equal protection of the laws."],
    ["Who appoints the Chief Justice of India?", ["The President", "The Prime Minister", "The Parliament"], "The President appoints the CJI under Article 124."], ["Minimum age to be elected President of India?", ["35 years", "30 years", "25 years"], "A candidate must be at least 35."], ["How many Schedules does the Constitution have now?", ["12", "8", "10"], "There are 12 Schedules."],
    ["Who is the first law officer of the Government of India?", ["Attorney General", "Solicitor General", "Law Minister"], "The Attorney General of India (Article 76)."], ["Freedom of speech and expression is in…", ["Article 19(1)(a)", "Article 21", "Article 25"], "Article 19(1)(a)."], ["The words 'Socialist' and 'Secular' were added to the Preamble by the…", ["42nd Amendment", "1st Amendment", "44th Amendment"], "Through the 42nd Amendment (1976)."]];
  let order, i, score;
  const next = () => { if (i >= 10) { if (score > Games.best("consti")) Games.setBest("consti", score); el.innerHTML = `<div class="cv-over static"><b>${score} / 10 correct${score === 10 ? " · flawless 🏆" : ""}</b><button class="btn btn-primary" type="button">Again</button></div>`; return (el.querySelector("button").onclick = start); }
    const [q, opts, note] = order[i], o = shuf(opts);
    el.innerHTML = `<div class="game-stats"><span>Question <b>${i + 1}</b>/10</span><span>Score <b>${score}</b></span><span>Best <b>${Games.best("consti")}</b></span></div><div class="cq-q">${q}</div><div class="mx-o">${o.map((x) => `<button type="button" class="mx-btn" data-ok="${x === opts[0] ? 1 : 0}">${x}</button>`).join("")}</div><p class="cq-note" hidden>${note}</p>`;
    el.querySelectorAll(".mx-btn").forEach((b) => (b.onclick = () => { el.querySelectorAll(".mx-btn").forEach((x) => { x.disabled = true; if (x.dataset.ok === "1") x.classList.add("ok"); }); if (b.dataset.ok === "1") score++; else b.classList.add("bad"); el.querySelector(".cq-note").hidden = false; i++; setTimeout(next, 1900); })); };
  const start = () => { order = shuf(Q).slice(0, 10); i = 0; score = 0; next(); };
  el.innerHTML = `<div class="game-stats"><span>Best <b>${Games.best("consti")}</b></span></div><div class="cv-over static"><b>Ten questions on the Indian Constitution.</b><button class="btn btn-primary" type="button">Start</button></div>`; el.querySelector("button").onclick = start;
};

// ---- Tile Merge (2048) ----
Games.merge = function () {
  const el = document.getElementById("merge"); if (!el) return;
  let g, score, over;
  const add = () => { const e = g.map((v, k) => (v ? -1 : k)).filter((k) => k >= 0); if (e.length) g[e[Math.floor(Math.random() * e.length)]] = Math.random() < 0.9 ? 2 : 4; };
  const slide = (row) => { const a = row.filter(Boolean); for (let k = 0; k < a.length - 1; k++) if (a[k] === a[k + 1]) { a[k] *= 2; score += a[k]; a.splice(k + 1, 1); } while (a.length < 4) a.push(0); return a; };
  const move = (d) => { if (over) return; const b = [...g];
    for (let n = 0; n < 4; n++) { const idx = [0, 1, 2, 3].map((k) => (d === "L" ? n * 4 + k : d === "R" ? n * 4 + 3 - k : d === "U" ? k * 4 + n : (3 - k) * 4 + n)); const r = slide(idx.map((k) => g[k])); idx.forEach((k, j) => (g[k] = r[j])); }
    if (b.join() === g.join()) return; add(); if (score > Games.best("merge")) Games.setBest("merge", score);
    over = !g.includes(0) && !["L", "R", "U", "D"].some((m) => { const s = score, c = [...g]; const t = []; for (let n = 0; n < 4; n++) { const idx = [0, 1, 2, 3].map((k) => (m === "L" ? n * 4 + k : m === "R" ? n * 4 + 3 - k : m === "U" ? k * 4 + n : (3 - k) * 4 + n)); const r = slide(idx.map((k) => c[k])); r.forEach((v, j) => (t[idx[j]] = v)); score = s; } return t.join() !== g.join(); });
    draw(); };
  const draw = () => { el.innerHTML = `<div class="game-stats"><span>Score <b>${score}</b></span><span>Best <b>${Games.best("merge")}</b></span><button class="btn btn-ghost tm-new" type="button">New game</button></div>
      <div class="tm-board">${g.map((v) => `<div class="tm-cell" data-v="${v}">${v || ""}</div>`).join("")}${over ? `<div class="cv-over"><b>No more moves · ${score}</b><button class="btn btn-primary tm-new" type="button">Play again</button></div>` : ""}</div>`;
    el.querySelectorAll(".tm-new").forEach((b) => (b.onclick = start)); };
  const start = () => { g = Array(16).fill(0); score = 0; over = false; add(); add(); draw(); };
  keyGuard("merge", (e) => { const m = { ArrowLeft: "L", ArrowRight: "R", ArrowUp: "U", ArrowDown: "D" }[e.key]; if (m) { e.preventDefault(); move(m); } });
  let sx, sy; el.addEventListener("pointerdown", (e) => { if (e.target.closest(".tm-board")) { sx = e.clientX; sy = e.clientY; } });
  el.addEventListener("pointerup", (e) => { if (sx == null) return; const dx = e.clientX - sx, dy = e.clientY - sy; sx = null; if (Math.hypot(dx, dy) < 24) return; move(Math.abs(dx) > Math.abs(dy) ? (dx > 0 ? "R" : "L") : dy > 0 ? "D" : "U"); });
  el.style.touchAction = "none"; start();
};

// ---- js/goals.js ----
// ============================================================
// GOALS — generic exam/track system. A user creates any goal
// they want (JEE, NEET, Boards, CLAT, College, custom) and adds
// subjects/sections + topics under it. Nothing is hardcoded.
// ============================================================

const Goals = {
  list: [],
  subjects: [],
  activeGoalId: null,

  async load() {
    const user = await DB.currentUser();
    if (!user) return;
    const [goalsList, subjectsList] = await Promise.all([
      DB.list("goals", { filters: { user_id: user.id }, order: "sort_order", ascending: true }),
      DB.list("subjects", { filters: { user_id: user.id }, order: "created_at", ascending: true }),
    ]);
    this.list = goalsList;
    this.subjects = subjectsList;
    if (!this.activeGoalId && this.list.length) this.activeGoalId = this.list.find((g) => !g.archived)?.id;
  },

  async render() {
    await this.load();
    const el = document.getElementById("page-goals");
    if (!this.list.filter((g) => !g.archived).length) {
      el.innerHTML = `
        <div class="page-header"><h2>Goals</h2></div>
        <div class="empty-panel empty-hero">
          <div class="empty-icon" aria-hidden="true">🎯</div>
          <h3>Start with one goal</h3>
          <p>A goal is whatever you're working toward. Add it, then track subjects, tests and study time under it.</p>
          <div class="chip-row" role="group" aria-label="Quick start">
            ${["JEE", "NEET", "CLAT", "Boards", "College"].map((n) => `<button type="button" class="chip" data-goal="${n}">${n}</button>`).join("")}
          </div>
          <button class="btn btn-primary" id="first-goal-btn">+ Custom goal</button>
        </div>`;
      document.getElementById("first-goal-btn").onclick = () => this.openGoalForm();
      el.querySelectorAll(".chip[data-goal]").forEach((c) => (c.onclick = () => {
        this.openGoalForm();
        const f = document.getElementById("goal-name");
        if (f) { f.value = c.dataset.goal; f.focus(); }
      }));
      return;
    }

    el.innerHTML = `
      <div class="page-header">
        <h2>Goals</h2>
        <div class="header-actions">
          <button class="btn btn-ghost" id="add-goal-btn">+ Add Goal</button>
          <button class="btn btn-primary" id="add-subject-btn">+ Add Subject</button>
        </div>
      </div>
      <div class="semester-tabs" id="goal-tabs"></div>
      <div id="subject-grid" class="subject-grid"></div>
    `;

    const active = this.list.filter((g) => !g.archived);
    const tabsEl = document.getElementById("goal-tabs");
    tabsEl.innerHTML = active
      .map((g) => `<button class="tab ${g.id === this.activeGoalId ? "active" : ""}" data-goal="${g.id}">${escapeHtml(g.name)}</button>`)
      .join("");
    tabsEl.querySelectorAll(".tab").forEach((tab) => {
      tab.onclick = () => {
        this.activeGoalId = tab.dataset.goal;
        this.render();
      };
    });

    document.getElementById("add-goal-btn").onclick = () => this.openGoalForm();
    document.getElementById("add-subject-btn").onclick = () => this.openSubjectForm();

    this.renderSubjectGrid();
  },

  openGoalForm(goal = null) {
    openModal(`
      <h3>${goal ? "Edit Goal" : "Add Goal"}</h3>
      <form id="goal-form">
        <label>Name<input required id="goal-name" placeholder="e.g. JEE, NEET, Boards, CLAT, College" value="${goal ? escapeHtml(goal.name) : ""}" /></label>
        <label>Description<textarea id="goal-desc">${goal ? escapeHtml(goal.description || "") : ""}</textarea></label>
        <label>Color<input type="color" id="goal-color" value="${goal?.color || "#6366f1"}" /></label>
        <div class="modal-actions">
          <button type="button" class="btn btn-ghost" id="goal-cancel">Cancel</button>
          <button type="submit" class="btn btn-primary">Save</button>
        </div>
      </form>
    `);
    document.getElementById("goal-cancel").onclick = closeModal;
    document.getElementById("goal-form").onsubmit = async (e) => {
      e.preventDefault();
      const payload = {
        name: document.getElementById("goal-name").value.trim(),
        description: document.getElementById("goal-desc").value.trim(),
        color: document.getElementById("goal-color").value,
      };
      if (!payload.name) return;
      let saved;
      if (goal) saved = await DB.update("goals", goal.id, payload);
      else saved = await DB.insert("goals", { ...payload, sort_order: this.list.length });
      closeModal();
      toast(goal ? "Goal updated." : "Goal added.");
      this.activeGoalId = saved.id;
      this.render();
    };
  },

  async renderSubjectGrid() {
    const grid = document.getElementById("subject-grid");
    const list = this.subjects.filter((s) => !s.archived && s.goal_id === this.activeGoalId);
    const goal = this.list.find((g) => g.id === this.activeGoalId);

    const headerRow = `<div class="goal-actions-row">
      <button class="link-btn" id="edit-goal-btn">Edit "${escapeHtml(goal?.name || "")}"</button>
      <button class="link-btn danger" id="archive-goal-btn">Archive Goal</button>
    </div>`;

    if (!list.length) {
      grid.innerHTML = `<p class="empty-state">No subjects yet under this goal. Add your first subject or section.</p>`;
    } else {
      const user = await DB.currentUser();
      const allTests = await DB.list("tests", { filters: { user_id: user.id, goal_id: this.activeGoalId } });

      grid.innerHTML = list
        .map((s) => {
          const tests = allTests.filter((t) => t.subject_id === s.id && t.total_marks);
          const scores = tests.map((t) => pct(t.marks_obtained, t.total_marks));
          const average = scores.length ? Math.round(avg(scores)) : null;
          return `
          <div class="subject-card" style="--card-accent:${s.color || "#6366f1"}" data-id="${s.id}">
            <div class="subject-card-top">
              <span class="subject-dot"></span>
              <h3>${escapeHtml(s.name)}</h3>
            </div>
            <p class="subject-desc">${escapeHtml(s.description || "")}</p>
            <div class="subject-stats">
              <span>${tests.length} test${tests.length === 1 ? "" : "s"}</span>
              <span>${average !== null ? average + "% avg" : "No tests yet"}</span>
            </div>
            <div class="subject-card-actions">
              <button class="link-btn" data-action="topics" data-id="${s.id}">Topics</button>
              <button class="link-btn" data-action="edit" data-id="${s.id}">Edit</button>
              <button class="link-btn danger" data-action="delete" data-id="${s.id}">Delete</button>
            </div>
          </div>`;
        })
        .join("");
    }

    document.querySelector("#page-goals .goal-actions-row")?.remove();
    grid.insertAdjacentHTML("beforebegin", headerRow);
    document.getElementById("edit-goal-btn").onclick = () => this.openGoalForm(goal);
    document.getElementById("archive-goal-btn").onclick = async () => {
      const ok = await confirmDialog("Archive this goal?", "Subjects and tests stay in your history. You can keep using other goals.", "Archive", false);
      if (!ok) return;
      await DB.update("goals", goal.id, { archived: true });
      this.activeGoalId = null;
      toast("Goal archived.");
      this.render();
    };

    grid.querySelectorAll("[data-action]").forEach((btn) => {
      btn.addEventListener("click", () => {
        const id = btn.dataset.id;
        const subject = this.subjects.find((s) => s.id === id);
        if (btn.dataset.action === "edit") this.openSubjectForm(subject);
        if (btn.dataset.action === "delete") this.deleteSubjectFlow(subject);
        if (btn.dataset.action === "topics") this.openTopicsPanel(subject);
      });
    });
  },

  openSubjectForm(subject = null) {
    if (!this.list.filter((g) => !g.archived).length) {
      toast("Add a goal first.");
      return;
    }
    const goalOptions = this.list
      .filter((g) => !g.archived)
      .map((g) => `<option value="${g.id}" ${(subject?.goal_id || this.activeGoalId) === g.id ? "selected" : ""}>${escapeHtml(g.name)}</option>`)
      .join("");

    openModal(`
      <h3>${subject ? "Edit Subject" : "Add Subject"}</h3>
      <form id="subject-form">
        <label>Goal<select id="subj-goal">${goalOptions}</select></label>
        <label>Subject/Section Name<input required id="subj-name" value="${subject ? escapeHtml(subject.name) : ""}" /></label>
        <label>Description<textarea id="subj-desc">${subject ? escapeHtml(subject.description || "") : ""}</textarea></label>
        <label>Color<input type="color" id="subj-color" value="${subject?.color || "#6366f1"}" /></label>
        <div class="modal-actions">
          <button type="button" class="btn btn-ghost" id="subj-cancel">Cancel</button>
          <button type="submit" class="btn btn-primary">Save</button>
        </div>
      </form>
    `);
    document.getElementById("subj-cancel").onclick = closeModal;
    document.getElementById("subject-form").onsubmit = async (e) => {
      e.preventDefault();
      const payload = {
        goal_id: document.getElementById("subj-goal").value,
        name: document.getElementById("subj-name").value.trim(),
        description: document.getElementById("subj-desc").value.trim(),
        color: document.getElementById("subj-color").value,
      };
      if (!payload.name) return;
      if (subject) await DB.update("subjects", subject.id, payload);
      else await DB.insert("subjects", payload);
      closeModal();
      toast(subject ? "Subject updated." : "Subject added.");
      this.activeGoalId = payload.goal_id;
      this.render();
    };
  },

  async deleteSubjectFlow(subject) {
    openModal(`
      <h3>Delete Subject?</h3>
      <p class="modal-body-text">"${escapeHtml(subject.name)}" has related tests and study sessions. Archiving keeps your history intact and is usually the better choice.</p>
      <div class="modal-actions" style="flex-wrap:wrap">
        <button class="btn btn-ghost" id="del-cancel">Cancel</button>
        <button class="btn btn-secondary" id="del-archive">Archive Subject</button>
        <button class="btn btn-danger" id="del-permanent">Delete Permanently</button>
      </div>
      <p class="fine-print">Deleting permanently will also remove linked tests and study session references.</p>
    `);
    document.getElementById("del-cancel").onclick = closeModal;
    document.getElementById("del-archive").onclick = async () => {
      await DB.update("subjects", subject.id, { archived: true });
      closeModal();
      toast("Subject archived.");
      this.render();
    };
    document.getElementById("del-permanent").onclick = async () => {
      const ok = await confirmDialog("Are you sure?", "This permanently deletes the subject and cannot be undone.", "Delete Permanently");
      if (!ok) return;
      await DB.remove("subjects", subject.id);
      toast("Subject deleted.");
      this.render();
    };
  },

  async openTopicsPanel(subject) {
    const topics = await DB.list("topics", { filters: { subject_id: subject.id } });
    openModal(`
      <h3>${escapeHtml(subject.name)} — Topics</h3>
      <div id="topic-list" class="topic-list">
        ${topics.length ? topics.map((t) => `
          <div class="topic-row" data-id="${t.id}">
            <span>${escapeHtml(t.name)}</span>
            <div>
              <button class="link-btn" data-action="edit-topic" data-id="${t.id}">Edit</button>
              <button class="link-btn danger" data-action="del-topic" data-id="${t.id}">Delete</button>
            </div>
          </div>`).join("") : `<p class="empty-state">No topics yet.</p>`}
      </div>
      <form id="topic-form" class="inline-form">
        <input id="topic-name" placeholder="Add topic" required />
        <button type="submit" class="btn btn-primary">Add</button>
      </form>
      <div class="modal-actions"><button class="btn btn-ghost" id="topics-close">Close</button></div>
    `);
    document.getElementById("topics-close").onclick = closeModal;
    document.getElementById("topic-form").onsubmit = async (e) => {
      e.preventDefault();
      const name = document.getElementById("topic-name").value.trim();
      if (!name) return;
      await DB.insert("topics", { subject_id: subject.id, name });
      this.openTopicsPanel(subject);
    };
    document.querySelectorAll("[data-action='del-topic']").forEach((btn) => {
      btn.onclick = async () => {
        await DB.remove("topics", btn.dataset.id);
        this.openTopicsPanel(subject);
      };
    });
    document.querySelectorAll("[data-action='edit-topic']").forEach((btn) => {
      btn.onclick = async () => {
        const row = btn.closest(".topic-row");
        const current = row.querySelector("span").textContent;
        const name = await promptDialog("Rename topic", "Topic name", current);
        if (name) await DB.update("topics", btn.dataset.id, { name });
        this.openTopicsPanel(subject);
      };
    });
  },
};

// ---- js/tests.js ----
// ============================================================
// TESTS — works for any goal (JEE mocks, NEET mocks, CLAT mocks,
// college exams, board exams...). Filtered by the active goal.
// ============================================================

const Tests = {
  list: [],

  async load(goalId = null) {
    const user = await DB.currentUser();
    if (!user) return;
    const filters = { user_id: user.id };
    if (goalId) filters.goal_id = goalId;
    this.list = await DB.list("tests", { filters, order: "test_date", ascending: false });
  },

  async render() {
    await Goals.load();
    await this.load();
    const el = document.getElementById("page-tests");
    if (!Goals.list.filter((g) => !g.archived).length) {
      el.innerHTML = `<div class="page-header"><h2>Tests</h2></div><p class="empty-state">Add a goal first (Goals page), then come back to log tests.</p>`;
      return;
    }
    const goalOptions = Goals.list
      .filter((g) => !g.archived)
      .map((g) => `<option value="${g.id}">${escapeHtml(g.name)}</option>`)
      .join("");

    el.innerHTML = `
      <div class="page-header">
        <h2>Tests</h2>
        <button class="btn btn-primary" id="add-test-btn">+ Add Test</button>
      </div>
      <div class="semester-tabs" id="test-goal-tabs">
        ${Goals.list.filter((g) => !g.archived).map((g, i) => `<button class="tab ${i === 0 ? "active" : ""}" data-goal="${g.id}">${escapeHtml(g.name)}</button>`).join("")}
        <button class="tab" data-goal="all">All</button>
      </div>
      <div id="test-list" class="record-list"></div>
    `;
    document.getElementById("add-test-btn").onclick = () => this.openForm();
    const tabsEl = document.getElementById("test-goal-tabs");
    tabsEl.querySelectorAll(".tab").forEach((tab) => {
      tab.onclick = () => {
        tabsEl.querySelectorAll(".tab").forEach((t) => t.classList.remove("active"));
        tab.classList.add("active");
        this.renderList(tab.dataset.goal);
      };
    });
    this.renderList(Goals.list.filter((g) => !g.archived)[0]?.id);
  },

  renderList(goalFilter) {
    const el = document.getElementById("test-list");
    const filtered = goalFilter === "all" ? this.list : this.list.filter((t) => t.goal_id === goalFilter);
    if (!filtered.length) {
      el.innerHTML = `<p class="empty-state">No tests recorded yet.</p>`;
      return;
    }
    el.innerHTML = filtered
      .map((t) => {
        const subject = Goals.subjects.find((s) => s.id === t.subject_id);
        const goal = Goals.list.find((g) => g.id === t.goal_id);
        const percentage = t.total_marks ? pct(t.marks_obtained, t.total_marks) : null;
        const accuracy = t.attempted ? pct(t.correct, t.attempted) : null;
        return `
        <div class="record-card">
          <div class="record-main">
            <strong>${escapeHtml(t.name)}</strong>
            <span class="muted">${escapeHtml(goal?.name || "")}${subject ? " · " + escapeHtml(subject.name) : ""} · ${fmtDate(t.test_date)}</span>
          </div>
          <div class="record-stats">
            ${percentage !== null ? `<span>${percentage}%</span>` : ""}
            ${accuracy !== null ? `<span>${accuracy}% accuracy</span>` : ""}
          </div>
          <div class="record-actions">
            <button class="link-btn" data-action="edit" data-id="${t.id}">Edit</button>
            <button class="link-btn danger" data-action="delete" data-id="${t.id}">Delete</button>
          </div>
        </div>`;
      })
      .join("");

    el.querySelectorAll("[data-action]").forEach((btn) => {
      btn.addEventListener("click", () => {
        const test = this.list.find((t) => t.id === btn.dataset.id);
        if (btn.dataset.action === "edit") this.openForm(test);
        if (btn.dataset.action === "delete") this.deleteFlow(test);
      });
    });
  },

  openForm(test = null) {
    const activeGoals = Goals.list.filter((g) => !g.archived);
    const goalOptions = activeGoals
      .map((g) => `<option value="${g.id}" ${(test?.goal_id || Goals.activeGoalId) === g.id ? "selected" : ""}>${escapeHtml(g.name)}</option>`)
      .join("");

    openModal(`
      <h3>${test ? "Edit Test" : "Add Test"}</h3>
      <form id="test-form" class="grid-form">
        <label>Goal<select id="t-goal">${goalOptions}</select></label>
        <label>Test name<input required id="t-name" value="${test ? escapeHtml(test.name) : ""}" /></label>
        <label>Subject/Section<select id="t-subject"><option value="">—</option></select></label>
        <label>Date<input type="date" id="t-date" value="${test?.test_date || todayStr()}" /></label>
        <label>Total marks<input type="number" id="t-total-marks" value="${test?.total_marks ?? ""}" /></label>
        <label>Marks obtained<input type="number" id="t-marks" value="${test?.marks_obtained ?? ""}" /></label>
        <label>Total questions<input type="number" id="t-total-q" value="${test?.total_questions ?? ""}" /></label>
        <label>Attempted<input type="number" id="t-attempted" value="${test?.attempted ?? ""}" /></label>
        <label>Correct<input type="number" id="t-correct" value="${test?.correct ?? ""}" /></label>
        <label>Incorrect<input type="number" id="t-incorrect" value="${test?.incorrect ?? ""}" /></label>
        <label>Time taken (min)<input type="number" id="t-time" value="${test?.time_taken_min ?? ""}" /></label>
        <label class="full">Notes<textarea id="t-notes">${test ? escapeHtml(test.notes || "") : ""}</textarea></label>
        <div class="modal-actions full">
          <button type="button" class="btn btn-ghost" id="t-cancel">Cancel</button>
          <button type="submit" class="btn btn-primary">Save</button>
        </div>
      </form>
    `);

    const goalSelect = document.getElementById("t-goal");
    const subjectSelect = document.getElementById("t-subject");
    const refreshSubjects = () => {
      const subs = Goals.subjects.filter((s) => !s.archived && s.goal_id === goalSelect.value);
      subjectSelect.innerHTML = `<option value="">—</option>` + subs.map((s) => `<option value="${s.id}" ${test?.subject_id === s.id ? "selected" : ""}>${escapeHtml(s.name)}</option>`).join("");
    };
    goalSelect.addEventListener("change", refreshSubjects);
    refreshSubjects();

    document.getElementById("t-cancel").onclick = closeModal;
    document.getElementById("test-form").onsubmit = async (e) => {
      e.preventDefault();
      const totalQ = numOrNull("t-total-q");
      const attempted = numOrNull("t-attempted");
      const unattempted = totalQ != null && attempted != null ? totalQ - attempted : null;

      const payload = {
        goal_id: goalSelect.value,
        subject_id: subjectSelect.value || null,
        name: document.getElementById("t-name").value.trim(),
        test_date: document.getElementById("t-date").value,
        total_marks: numOrNull("t-total-marks"),
        marks_obtained: numOrNull("t-marks"),
        total_questions: totalQ,
        attempted,
        correct: numOrNull("t-correct"),
        incorrect: numOrNull("t-incorrect"),
        unattempted,
        time_taken_min: numOrNull("t-time"),
        notes: document.getElementById("t-notes").value.trim(),
      };
      if (!payload.name || !payload.goal_id) return;

      let saved;
      if (test) saved = await DB.update("tests", test.id, payload);
      else saved = await DB.insert("tests", payload);

      if (!test) {
        await DB.reward("xp_test", 25, "test", "test", `Added "${payload.name}" test`, saved.id);
      }
      closeModal();
      toast("Test saved.");
      this.render();
    };
  },

  async deleteFlow(test) {
    openModal(`
      <h3>Delete this test?</h3>
      <p class="modal-body-text">Deleting this record will remove it from history, graphs and performance calculations.</p>
      <div class="modal-actions">
        <button class="btn btn-ghost" id="dt-cancel">Cancel</button>
        <button class="btn btn-danger" id="dt-ok">Delete</button>
      </div>
    `);
    document.getElementById("dt-cancel").onclick = closeModal;
    document.getElementById("dt-ok").onclick = async () => {
      await DB.remove("tests", test.id);
      closeModal();
      toast("Test deleted.");
      this.render();
    };
  },
};

function numOrNull(id) {
  const v = document.getElementById(id).value;
  return v === "" ? null : Number(v);
}

// ---- js/study.js ----
// ============================================================
// STUDY — Timer (count-up stopwatch) + Pomodoro. Both can be
// tagged to any Goal + Subject + Topic, or left as "Personal"
// (no goal). State lives on this object so it survives
// switching tabs/pages without losing a running timer.
// ============================================================

const Study = {
  activeTab: "timer",
  displayMode: localStorage.getItem("clockDisplayMode") || "digital",

  // ---- stopwatch state ----
  timer: {
    running: false,
    startedAt: null,
    elapsedMs: 0,
    intervalId: null,
    goalId: "",
    subjectId: "",
    topicText: "",
  },

  // ---- pomodoro state ----
  pomo: {
    phase: "work", // work | short_break | long_break
    running: false,
    remainingSec: 0,
    intervalId: null,
    sessionsCompleted: 0,
    settings: null,
    goalId: "",
    subjectId: "",
    topicText: "",
  },

  async render() {
    await Goals.load();
    const el = document.getElementById("page-study");
    el.innerHTML = `
      <div class="page-header"><h2>Study</h2></div>
      <div class="tabs" id="study-tabs">
        <button class="tab ${this.activeTab === "timer" ? "active" : ""}" data-tab="timer">Timer</button>
        <button class="tab ${this.activeTab === "pomodoro" ? "active" : ""}" data-tab="pomodoro">Pomodoro</button>
      </div>
      <div id="study-body"></div>
      <div class="panel" id="study-history-panel">
        <h3>Recent Sessions</h3>
        <div id="study-history"></div>
      </div>
    `;
    document.querySelectorAll("#study-tabs .tab").forEach((t) => {
      t.onclick = () => {
        this.activeTab = t.dataset.tab;
        this.render();
      };
    });
    if (this.activeTab === "timer") this.renderTimer();
    else this.renderPomodoro();
    this.renderHistory();
  },

  toggleDisplayModeHtml() {
    return `
      <div class="display-mode-toggle">
        <button class="dm-btn ${this.displayMode === "digital" ? "active" : ""}" data-mode="digital">🔢 Digital</button>
        <button class="dm-btn ${this.displayMode === "analog" ? "active" : ""}" data-mode="analog">🕐 Analog</button>
        <button class="dm-btn" data-fx="focus" type="button">⛶ Focus</button>
      </div>`;
  },

  wireDisplayModeToggle(onChange) {
    document.querySelectorAll(".dm-btn[data-mode]").forEach((btn) => {
      btn.onclick = () => {
        this.displayMode = btn.dataset.mode;
        localStorage.setItem("clockDisplayMode", this.displayMode);
        onChange();
      };
    });
  },

  // ============================================================
  // GOAL/SUBJECT PICKER (shared markup for both timer & pomodoro)
  // ============================================================
  goalPickerHtml(prefix, state) {
    const activeGoals = Goals.list.filter((g) => !g.archived);
    return `
      <div class="tag-picker">
        <label>Goal
          <select id="${prefix}-goal">
            <option value="">Personal (no goal)</option>
            ${activeGoals.map((g) => `<option value="${g.id}" ${state.goalId === g.id ? "selected" : ""}>${escapeHtml(g.name)}</option>`).join("")}
          </select>
        </label>
        <label>Subject
          <select id="${prefix}-subject"><option value="">—</option></select>
        </label>
        <label>Topic
          <input id="${prefix}-topic" placeholder="optional" value="${escapeHtml(state.topicText || "")}" />
        </label>
      </div>`;
  },

  wireGoalPicker(prefix, state) {
    const goalSel = document.getElementById(`${prefix}-goal`);
    const subjSel = document.getElementById(`${prefix}-subject`);
    const topicInput = document.getElementById(`${prefix}-topic`);
    const refreshSubjects = () => {
      const subs = Goals.subjects.filter((s) => !s.archived && s.goal_id === goalSel.value);
      subjSel.innerHTML = `<option value="">—</option>` + subs.map((s) => `<option value="${s.id}" ${state.subjectId === s.id ? "selected" : ""}>${escapeHtml(s.name)}</option>`).join("");
    };
    goalSel.value = state.goalId || "";
    refreshSubjects();
    goalSel.onchange = () => { state.goalId = goalSel.value; state.subjectId = ""; refreshSubjects(); };
    subjSel.onchange = () => { state.subjectId = subjSel.value; };
    topicInput.oninput = () => { state.topicText = topicInput.value; };
  },

  // ============================================================
  // TIMER
  // ============================================================
  renderTimer() {
    const body = document.getElementById("study-body");
    const disabled = this.timer.running || this.timer.elapsedMs > 0;
    body.innerHTML = `
      <div class="panel timer-panel">
        ${this.toggleDisplayModeHtml()}
        <div id="timer-face">
          ${this.displayMode === "analog" ? `<div class="clock-face-wrap"></div>` : `<div class="timer-display" id="timer-display">${fmtStopwatch(this.timer.elapsedMs)}</div><div class="clock-bar"><i id="clock-bar-fill" style="transform:scaleX(${((this.timer.elapsedMs % 60000) / 60000).toFixed(3)})"></i></div>`}
        </div>
        <div class="timer-controls">
          ${!this.timer.running && this.timer.elapsedMs === 0 ? `<button class="btn btn-primary" id="timer-start">Start</button>` : ""}
          ${this.timer.running ? `<button class="btn btn-secondary" id="timer-pause">Pause</button>` : ""}
          ${!this.timer.running && this.timer.elapsedMs > 0 ? `<button class="btn btn-secondary" id="timer-resume">Resume</button>` : ""}
          ${this.timer.elapsedMs > 0 ? `<button class="btn btn-primary" id="timer-stop">Stop &amp; Save</button>` : ""}
          ${this.timer.elapsedMs > 0 && !this.timer.running ? `<button class="btn btn-ghost" id="timer-reset">Reset</button>` : ""}
        </div>
        <fieldset ${disabled ? "disabled" : ""} style="border:none;padding:0;margin-top:16px;">
          ${this.goalPickerHtml("timer", this.timer)}
        </fieldset>
      </div>
    `;
    this.wireDisplayModeToggle(() => this.renderTimer());
    if (this.displayMode === "analog") this.paintTimerFace();
    this.wireGoalPicker("timer", this.timer);
    document.getElementById("timer-start")?.addEventListener("click", () => this.startTimer());
    document.getElementById("timer-pause")?.addEventListener("click", () => this.pauseTimer());
    document.getElementById("timer-resume")?.addEventListener("click", () => this.startTimer());
    document.getElementById("timer-stop")?.addEventListener("click", () => this.openSaveSession());
    document.getElementById("timer-reset")?.addEventListener("click", () => {
      this.timer.elapsedMs = 0;
      this.renderTimer();
    });
  },

  paintTimerFace() {
    const wrap = document.querySelector("#timer-face .clock-face-wrap");
    if (wrap) renderAnalogClock(wrap, Math.floor(this.timer.elapsedMs / 1000), fmtStopwatch(this.timer.elapsedMs));
  },

  startTimer() {
    this.timer.running = true;
    this.timer.startedAt = Date.now() - this.timer.elapsedMs;
    this.timer.intervalId = setInterval(() => {
      this.timer.elapsedMs = Date.now() - this.timer.startedAt;
      if (this.displayMode === "analog") {
        this.paintTimerFace();
      } else {
        const disp = document.getElementById("timer-display");
        setDigits(disp, fmtStopwatch(this.timer.elapsedMs));
      }
    }, 1000);
    this.animateFace("timer");
    this.renderTimer();
  },

  // analog hands sweep smoothly (every frame) instead of jumping once a second
  animateFace(kind) {
    cancelAnimationFrame(this._raf);
    const step = () => {
      const t = kind === "timer" ? this.timer : this.pomo;
      if (!t.running) return;
      const fill = document.getElementById("clock-bar-fill");
      if (fill) {
        const f = kind === "timer" ? ((Date.now() - t.startedAt) % 60000) / 60000 : 1 - Math.max(0, t.endAt - Date.now()) / 1000 / (t.totalSec || 1);
        fill.style.transform = `scaleX(${Math.min(1, Math.max(0, f)).toFixed(4)})`;
      }
      if (this.displayMode === "analog") {
        const wrap = document.querySelector(kind === "timer" ? "#timer-face .clock-face-wrap" : "#pomo-face .clock-face-wrap");
        if (wrap) {
          if (kind === "timer") { const ms = Date.now() - t.startedAt; renderAnalogClock(wrap, ms / 1000, fmtStopwatch(ms)); }
          else { const ms = Math.max(0, t.endAt - Date.now()); renderAnalogClock(wrap, ms / 1000, fmtCountdown(Math.round(ms / 1000))); }
        }
      }
      this._raf = requestAnimationFrame(step);
    };
    this._raf = requestAnimationFrame(step);
  },

  pauseTimer() {
    this.timer.running = false;
    clearInterval(this.timer.intervalId);
    this.renderTimer();
  },

  openSaveSession() {
    if (this.timer.running) this.pauseTimer();
    const mins = Math.round(this.timer.elapsedMs / 60000);
    openModal(`
      <h3>Save Study Session</h3>
      <p class="modal-body-text">${mins} minute${mins === 1 ? "" : "s"} recorded.</p>
      <form id="save-session-form">
        <label>Notes<textarea id="session-notes" placeholder="optional"></textarea></label>
        <div class="modal-actions">
          <button type="button" class="btn btn-ghost" id="ss-cancel">Discard</button>
          <button type="submit" class="btn btn-primary">Save</button>
        </div>
      </form>
    `);
    document.getElementById("ss-cancel").onclick = () => {
      closeModal();
      this.timer.elapsedMs = 0;
      this.renderTimer();
    };
    document.getElementById("save-session-form").onsubmit = async (e) => {
      e.preventDefault();
      const durationSec = Math.round(this.timer.elapsedMs / 1000);
      if (durationSec < 10) {
        toast("Too short to save.");
        closeModal();
        this.timer.elapsedMs = 0;
        this.renderTimer();
        return;
      }
      const endTime = new Date();
      const startTime = new Date(endTime.getTime() - durationSec * 1000);
      const payload = {
        goal_id: this.timer.goalId || null,
        subject_id: this.timer.subjectId || null,
        topic_text: this.timer.topicText || null,
        start_time: startTime.toISOString(),
        end_time: endTime.toISOString(),
        duration_sec: durationSec,
        notes: document.getElementById("session-notes").value.trim(),
      };
      const saved = await DB.insert("study_sessions", payload);
      await DB.reward("xp_study_session", 15, "study_session", "study_session", `Studied for ${fmtDuration(durationSec)}`, saved.id);
      closeModal();
      toast("Study session saved.");
      this.timer.elapsedMs = 0;
      this.timer.subjectId = "";
      this.timer.topicText = "";
      this.render();
    };
  },

  // ============================================================
  // POMODORO
  // ============================================================
  async renderPomodoro() {
    if (!this.pomo.settings) {
      this.pomo.settings = await DB.getSettings();
      this.pomo.remainingSec = (this.pomo.settings?.pomodoro_work_min ?? 25) * 60; this.pomo.totalSec = this.pomo.remainingSec;
    }
    const s = this.pomo.settings;
    if (!this.pomo.today) await this.loadPomoToday();
    const { count: todayCount, minutes: todayMinutes } = this.pomo.today;

    const body = document.getElementById("study-body");
    const phaseLabel = { work: "Focus", short_break: "Short Break", long_break: "Long Break" }[this.pomo.phase];
    const disabled = this.pomo.running || this.pomo.sessionsCompleted > 0;

    body.innerHTML = `
      <div class="panel timer-panel">
        ${this.toggleDisplayModeHtml()}
        <div class="pomo-phase-label">${phaseLabel}</div>
        <div id="pomo-face">
          ${this.displayMode === "analog" ? `<div class="clock-face-wrap"></div>` : `<div class="timer-display" id="pomo-display">${fmtCountdown(this.pomo.remainingSec)}</div><div class="clock-bar"><i id="clock-bar-fill" style="transform:scaleX(${(1 - this.pomo.remainingSec / (this.pomo.totalSec || this.pomo.remainingSec || 1)).toFixed(3)})"></i></div>`}
        </div>
        <div class="timer-controls">
          ${!this.pomo.running ? `<button class="btn btn-primary" id="pomo-start">Start</button>` : `<button class="btn btn-secondary" id="pomo-pause">Pause</button>`}
          <button class="btn btn-ghost" id="pomo-skip">Skip</button>
          <button class="btn btn-ghost" id="pomo-reset">Reset</button>
        </div>
        <div class="pomo-stats-row">
          <span>Cycle: ${this.pomo.sessionsCompleted % s.pomodoro_sessions_before_long}/${s.pomodoro_sessions_before_long}</span>
          <span>Today: ${todayCount} pomodoros · ${fmtDuration(todayMinutes * 60)}</span>
        </div>
        <fieldset ${disabled ? "disabled" : ""} style="border:none;padding:0;margin-top:14px;">
          ${this.goalPickerHtml("pomo", this.pomo)}
        </fieldset>
        <details class="pomo-customize">
          <summary>Customize timings</summary>
          <div class="grid-form" style="margin-top:10px;">
            <label>Work (min)<input type="number" id="cfg-work" value="${s.pomodoro_work_min}" min="1" /></label>
            <label>Short break (min)<input type="number" id="cfg-short" value="${s.pomodoro_short_break_min}" min="1" /></label>
            <label>Long break (min)<input type="number" id="cfg-long" value="${s.pomodoro_long_break_min}" min="1" /></label>
            <label>Sessions before long break<input type="number" id="cfg-sessions" value="${s.pomodoro_sessions_before_long}" min="1" /></label>
            <button class="btn btn-secondary full" id="cfg-save" type="button">Save Timings</button>
          </div>
        </details>
      </div>
    `;
    this.wireGoalPicker("pomo", this.pomo);
    this.wireDisplayModeToggle(() => this.renderPomodoro());
    if (this.displayMode === "analog") this.paintPomoFace();
    document.getElementById("pomo-start")?.addEventListener("click", () => this.startPomodoro());
    document.getElementById("pomo-pause")?.addEventListener("click", () => this.pausePomodoro());
    document.getElementById("pomo-skip")?.addEventListener("click", () => this.advancePomodoroPhase(false));
    document.getElementById("pomo-reset")?.addEventListener("click", () => this.resetPomodoro());
    document.getElementById("cfg-save")?.addEventListener("click", async () => {
      const user2 = await DB.currentUser();
      const patch = {
        pomodoro_work_min: Number(document.getElementById("cfg-work").value) || 25,
        pomodoro_short_break_min: Number(document.getElementById("cfg-short").value) || 5,
        pomodoro_long_break_min: Number(document.getElementById("cfg-long").value) || 15,
        pomodoro_sessions_before_long: Number(document.getElementById("cfg-sessions").value) || 4,
      };
      await DB.client.from("user_settings").update(patch).eq("user_id", user2.id);
      this.pomo.settings = { ...this.pomo.settings, ...patch };
      this.resetPomodoro();
      toast("Pomodoro timings saved.");
    });
  },

  async loadPomoToday() {
    const user = await DB.currentUser();
    const { start } = dayBounds(todayStr());
    const rows = await DB.list("pomodoros", { filters: { user_id: user.id }, columns: "duration_min", gte: { completed_at: start } });
    this.pomo.today = { count: rows.length, minutes: rows.reduce((sum, p) => sum + (p.duration_min || 0), 0) };
  },

  startPomodoro() {
    this.pomo.running = true;
    // count down from a fixed end time so background-tab throttling can't slow the clock
    const endAt = (this.pomo.endAt = Date.now() + this.pomo.remainingSec * 1000);
    this.pomo.intervalId = setInterval(() => {
      this.pomo.remainingSec = Math.max(0, Math.round((endAt - Date.now()) / 1000));
      if (this.displayMode === "analog") {
        this.paintPomoFace();
      } else {
        const disp = document.getElementById("pomo-display");
        setDigits(disp, fmtCountdown(this.pomo.remainingSec));
      }
      if (this.pomo.remainingSec <= 0) {
        clearInterval(this.pomo.intervalId);
        this.advancePomodoroPhase(true);
      }
    }, 1000);
    this.animateFace("pomo");
    this.renderPomodoro();
  },

  paintPomoFace() {
    const wrap = document.querySelector("#pomo-face .clock-face-wrap");
    if (wrap) renderAnalogClock(wrap, this.pomo.remainingSec, fmtCountdown(this.pomo.remainingSec));
  },

  pausePomodoro() {
    this.pomo.running = false;
    clearInterval(this.pomo.intervalId);
    this.renderPomodoro();
  },

  async advancePomodoroPhase(completedNaturally) {
    clearInterval(this.pomo.intervalId);
    this.pomo.running = false;
    const s = this.pomo.settings;

    if (this.pomo.phase === "work") {
      if (completedNaturally) await this.saveCompletedPomodoro();
      this.pomo.sessionsCompleted++;
      const isLong = this.pomo.sessionsCompleted % s.pomodoro_sessions_before_long === 0;
      this.pomo.phase = isLong ? "long_break" : "short_break";
      this.pomo.remainingSec = (isLong ? s.pomodoro_long_break_min : s.pomodoro_short_break_min) * 60; this.pomo.totalSec = this.pomo.remainingSec;
    } else {
      this.pomo.phase = "work";
      this.pomo.remainingSec = s.pomodoro_work_min * 60; this.pomo.totalSec = this.pomo.remainingSec;
    }
    this.renderPomodoro();
    this.renderHistory();
  },

  async saveCompletedPomodoro() {
    const payload = {
      goal_id: this.pomo.goalId || null,
      subject_id: this.pomo.subjectId || null,
      topic_text: this.pomo.topicText || null,
      duration_min: this.pomo.settings.pomodoro_work_min,
      completed_at: new Date().toISOString(),
    };
    const saved = await DB.insert("pomodoros", payload);
    await DB.reward("xp_pomodoro", 10, "pomodoro", "pomodoro", `Completed a ${payload.duration_min}-minute Pomodoro`, saved.id);
    this.pomo.today = null; // recount next time the panel draws
    toast("Pomodoro complete. +XP");
  },

  resetPomodoro() {
    clearInterval(this.pomo.intervalId);
    this.pomo.running = false;
    this.pomo.phase = "work";
    this.pomo.sessionsCompleted = 0;
    this.pomo.remainingSec = (this.pomo.settings?.pomodoro_work_min ?? 25) * 60; this.pomo.totalSec = this.pomo.remainingSec;
    this.renderPomodoro();
  },

  // ============================================================
  // HISTORY (shared panel under both tabs)
  // ============================================================
  async renderHistory() {
    const el = document.getElementById("study-history");
    const user = await DB.currentUser();
    if (!user) return;
    const [sessions, pomos] = await Promise.all([
      DB.list("study_sessions", { filters: { user_id: user.id }, order: "start_time", ascending: false, limit: 8 }),
      DB.list("pomodoros", { filters: { user_id: user.id }, order: "completed_at", ascending: false, limit: 8 }),
    ]);

    const combined = [
      ...sessions.slice(0, 8).map((s) => ({ type: "Session", label: s.topic_text || "Study session", sub: fmtDuration(s.duration_sec), date: s.start_time, id: s.id, kind: "session" })),
      ...pomos.slice(0, 8).map((p) => ({ type: "Pomodoro", label: p.topic_text || "Pomodoro", sub: `${p.duration_min} min`, date: p.completed_at, id: p.id, kind: "pomodoro" })),
    ].sort((a, b) => new Date(b.date) - new Date(a.date)).slice(0, 10);

    if (!combined.length) {
      el.innerHTML = `<p class="empty-state">No study sessions or Pomodoros yet.</p>`;
      return;
    }
    el.innerHTML = combined
      .map((r) => `<div class="mini-row"><span>${r.type === "Pomodoro" ? "⏱" : "📖"} ${escapeHtml(r.label)}</span><span>${r.sub}</span><span class="muted">${fmtDate(r.date)}</span><button class=\"rec-del\" type=\"button\" data-del-kind=\"${r.kind}\" data-del-id=\"${r.id}\" title=\"Delete (asks for your password)\" aria-label=\"Delete this record\">🗑</button></div>`)
      .join("");
  },
};

function fmtStopwatch(ms) {
  const totalSec = Math.floor(ms / 1000);
  const h = Math.floor(totalSec / 3600);
  const m = Math.floor((totalSec % 3600) / 60);
  const s = totalSec % 60;
  return h > 0
    ? `${String(h).padStart(2, "0")}:${String(m).padStart(2, "0")}:${String(s).padStart(2, "0")}`
    : `${String(m).padStart(2, "0")}:${String(s).padStart(2, "0")}`;
}

function fmtCountdown(sec) {
  const s = Math.max(0, sec);
  const m = Math.floor(s / 60);
  const r = s % 60;
  return `${String(m).padStart(2, "0")}:${String(r).padStart(2, "0")}`;
}

// ---- js/tasks.js ----
// ============================================================
// TASKS
// ============================================================

const Tasks = {
  list: [],
  activeFilter: "all",

  async load() {
    const user = await DB.currentUser();
    if (!user) return;
    this.list = await DB.list("tasks", { filters: { user_id: user.id }, order: "due_date", ascending: true });
  },

  async render() {
    await Goals.load();
    await this.load();
    const el = document.getElementById("page-tasks");
    el.innerHTML = `
      <div class="page-header">
        <h2>Tasks</h2>
        <div class="page-actions">
          <button class="btn btn-ghost" id="import-task-btn">Import PDF / Excel</button>
          <button class="btn btn-primary" id="add-task-btn">+ Add Task</button>
        </div>
      </div>
      <div class="tabs" id="task-filters">
        ${["all", "today", "upcoming", "completed", "academic", "fitness", "personal"]
          .map((f) => `<button class="tab ${f === this.activeFilter ? "active" : ""}" data-filter="${f}">${f[0].toUpperCase() + f.slice(1)}</button>`)
          .join("")}
      </div>
      <div id="task-list" class="record-list"></div>
    `;
    document.getElementById("add-task-btn").onclick = () => this.openForm();
    document.getElementById("import-task-btn").onclick = () => TaskImport.open();
    document.querySelectorAll("#task-filters .tab").forEach((t) => {
      t.onclick = () => {
        document.querySelectorAll("#task-filters .tab").forEach((x) => x.classList.remove("active"));
        t.classList.add("active");
        this.activeFilter = t.dataset.filter;
        this.renderList();
      };
    });
    this.renderList();
  },

  filtered() {
    const today = todayStr();
    switch (this.activeFilter) {
      case "today":
        return this.list.filter((t) => t.due_date === today && t.status !== "completed");
      case "upcoming":
        return this.list.filter((t) => t.due_date && t.due_date > today && t.status !== "completed");
      case "completed":
        return this.list.filter((t) => t.status === "completed");
      case "academic":
      case "fitness":
      case "personal":
        return this.list.filter((t) => t.category === this.activeFilter);
      default:
        return this.list;
    }
  },

  renderList() {
    const el = document.getElementById("task-list");
    const list = this.filtered();
    if (!list.length) {
      el.innerHTML = `<p class="empty-state">No tasks here.</p>`;
      return;
    }
    el.innerHTML = list
      .map((t) => {
        const goal = Goals.list.find((g) => g.id === t.goal_id);
        const overdue = t.due_date && t.due_date < todayStr() && t.status !== "completed";
        return `
        <div class="record-card task-card ${t.status === "completed" ? "task-done" : ""}">
          <label class="task-check">
            <input type="checkbox" data-id="${t.id}" ${t.status === "completed" ? "checked" : ""} />
          </label>
          <div class="record-main">
            <strong>${escapeHtml(t.title)}</strong>
            <span class="muted">
              <span class="priority-dot priority-${t.priority}"></span>
              ${escapeHtml(t.category || "general")}${goal ? " · " + escapeHtml(goal.name) : ""}
              ${t.due_date ? " · " + (overdue ? `<span class="overdue">Overdue ${fmtDate(t.due_date)}</span>` : fmtDate(t.due_date)) : ""}
            </span>
          </div>
          <div class="record-actions">
            <button class="link-btn" data-action="edit" data-id="${t.id}">Edit</button>
            <button class="link-btn danger" data-action="delete" data-id="${t.id}">Delete</button>
          </div>
        </div>`;
      })
      .join("");

    el.querySelectorAll("input[type=checkbox]").forEach((cb) => {
      cb.addEventListener("change", () => this.toggleComplete(cb.dataset.id, cb.checked));
    });
    el.querySelectorAll("[data-action]").forEach((btn) => {
      btn.addEventListener("click", () => {
        const task = this.list.find((t) => t.id === btn.dataset.id);
        if (btn.dataset.action === "edit") this.openForm(task);
        if (btn.dataset.action === "delete") this.deleteFlow(task);
      });
    });
  },

  async toggleComplete(id, checked) {
    const task = this.list.find((t) => t.id === id);
    const wasCompleted = task.status === "completed";
    const patch = checked
      ? { status: "completed", completed_at: new Date().toISOString() }
      : { status: "pending", completed_at: null };
    await DB.update("tasks", id, patch);
    Object.assign(task, patch); // update the row on screen right away — no full reload

    if (checked && !wasCompleted) {
      if (await alreadyRewarded("task_complete", id)) toast("Task completed. (XP was already earned for this one.)");
      else {
        await DB.reward("xp_task", 10, "task_complete", "task", `Completed "${task.title}"`, id);
        toast("Task completed.");
      }
    }
    this.renderList();
  },

  openForm(task = null) {
    const activeGoals = Goals.list.filter((g) => !g.archived);
    openModal(`
      <h3>${task ? "Edit Task" : "Add Task"}</h3>
      <form id="task-form" class="grid-form">
        <label class="full">Title<input required id="task-title" value="${task ? escapeHtml(task.title) : ""}" /></label>
        <label class="full">Description<textarea id="task-desc">${task ? escapeHtml(task.description || "") : ""}</textarea></label>
        <label>Category
          <select id="task-category">
            <option value="academic" ${task?.category === "academic" ? "selected" : ""}>Academic</option>
            <option value="fitness" ${task?.category === "fitness" ? "selected" : ""}>Fitness</option>
            <option value="personal" ${!task || task?.category === "personal" ? "selected" : ""}>Personal</option>
          </select>
        </label>
        <label>Priority
          <select id="task-priority">
            <option value="high" ${task?.priority === "high" ? "selected" : ""}>High</option>
            <option value="medium" ${!task || task?.priority === "medium" ? "selected" : ""}>Medium</option>
            <option value="low" ${task?.priority === "low" ? "selected" : ""}>Low</option>
          </select>
        </label>
        <label>Goal (optional)
          <select id="task-goal">
            <option value="">—</option>
            ${activeGoals.map((g) => `<option value="${g.id}" ${task?.goal_id === g.id ? "selected" : ""}>${escapeHtml(g.name)}</option>`).join("")}
          </select>
        </label>
        <label>Due date<input type="date" id="task-due" value="${task?.due_date || ""}" /></label>
        <div class="modal-actions full">
          <button type="button" class="btn btn-ghost" id="task-cancel">Cancel</button>
          <button type="submit" class="btn btn-primary">Save</button>
        </div>
      </form>
    `);
    document.getElementById("task-cancel").onclick = closeModal;
    document.getElementById("task-form").onsubmit = async (e) => {
      e.preventDefault();
      const payload = {
        title: document.getElementById("task-title").value.trim(),
        description: document.getElementById("task-desc").value.trim(),
        category: document.getElementById("task-category").value,
        priority: document.getElementById("task-priority").value,
        goal_id: document.getElementById("task-goal").value || null,
        due_date: document.getElementById("task-due").value || null,
      };
      if (!payload.title) return;
      if (task) await DB.update("tasks", task.id, payload);
      else await DB.insert("tasks", { ...payload, status: "pending" });
      closeModal();
      toast(task ? "Task updated." : "Task added.");
      this.render();
    };
  },

  async deleteFlow(task) {
    const ok = await confirmDialog("Delete this task?", "This can't be undone.", "Delete");
    if (!ok) return;
    await DB.remove("tasks", task.id);
    toast("Task deleted.");
    this.render();
  },
};

// ---- js/taskimport.js ----
// ============================================================
// TASK IMPORT — upload a PDF / Excel / CSV / TXT and Michi turns
// it into a to-do list. Everything is parsed in the browser (the
// file never leaves the device). You get a preview first, so you
// can edit / untick anything before it is saved.
//
// Libraries (SheetJS for Excel, pdf.js for PDF) are loaded only
// when you actually pick a file of that type, so the app stays fast.
// ============================================================

const TaskImport = {
  MAX_BYTES: 10 * 1024 * 1024,
  MAX_TASKS: 300,
  MAX_PDF_PAGES: 60,
  LIBS: {
    xlsx: "https://cdnjs.cloudflare.com/ajax/libs/xlsx/0.18.5/xlsx.full.min.js",
    pdf: "https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.min.js",
    pdfWorker: "https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js",
  },
  _loading: {},
  rows: [],

  // ---------- script loader ----------
  loadScript(src) {
    if (this._loading[src]) return this._loading[src];
    this._loading[src] = new Promise((resolve, reject) => {
      const s = document.createElement("script");
      s.src = src;
      s.onload = resolve;
      s.onerror = () => {
        delete this._loading[src];
        reject(new Error("Couldn't load the file reader. Check your internet and try again."));
      };
      document.head.appendChild(s);
    });
    return this._loading[src];
  },

  // ---------- step 1: pick a file ----------
  open() {
    openModal(`
      <h3>Import tasks from a file</h3>
      <p class="muted" style="font-size:13px;margin:0 0 12px">Upload a PDF, Excel sheet, CSV or text file — Michi reads it and builds your to-do list. You can review everything before it's saved.</p>
      <label class="imp-drop" id="imp-drop">
        <input type="file" id="imp-file" accept=".pdf,.xlsx,.xls,.csv,.txt,application/pdf,application/vnd.ms-excel,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet,text/csv,text/plain" hidden />
        <b>Choose a file</b>
        <span>or drag &amp; drop it here</span>
        <small>PDF · XLSX · XLS · CSV · TXT — up to 10 MB</small>
      </label>
      <details class="imp-sample"><summary>See a sample file (what the format looks like)</summary>
        <img src="assets/sample-tasks.png" alt="Sample task file: an Excel sheet with Task, Due date, Priority and Category columns, and a text list with one task per line" loading="lazy" />
        <p class="muted" style="font-size:12px;margin:8px 0 0">Tip for Excel: a header row like <i>Task · Due date · Priority</i> is picked up automatically. <a href="assets/sample-tasks.csv" download>Download the sample CSV</a> and replace the rows with yours.</p></details>
      <div id="imp-status" class="imp-status" hidden></div>
      <div class="modal-actions"><button type="button" class="btn btn-ghost" id="imp-cancel">Cancel</button></div>
    `);
    document.getElementById("imp-cancel").onclick = closeModal;
    const input = document.getElementById("imp-file");
    const drop = document.getElementById("imp-drop");
    input.onchange = () => input.files[0] && this.handleFile(input.files[0]);
    ["dragenter", "dragover"].forEach((ev) =>
      drop.addEventListener(ev, (e) => { e.preventDefault(); drop.classList.add("over"); })
    );
    ["dragleave", "drop"].forEach((ev) =>
      drop.addEventListener(ev, (e) => { e.preventDefault(); drop.classList.remove("over"); })
    );
    drop.addEventListener("drop", (e) => {
      const f = e.dataTransfer?.files?.[0];
      if (f) this.handleFile(f);
    });
  },

  setStatus(msg, isError = false) {
    const el = document.getElementById("imp-status");
    if (!el) return;
    el.hidden = !msg;
    el.textContent = msg || "";
    el.classList.toggle("err", !!isError);
  },

  async handleFile(file) {
    const ext = (file.name.split(".").pop() || "").toLowerCase();
    if (file.size > this.MAX_BYTES) return this.setStatus("That file is over 10 MB. Try a smaller one.", true);
    if (!["pdf", "xlsx", "xls", "csv", "txt"].includes(ext))
      return this.setStatus("Please pick a PDF, Excel (.xlsx/.xls), CSV or TXT file.", true);

    try {
      this.setStatus("Reading your file…");
      let items;
      if (ext === "pdf") items = await this.parsePdf(file);
      else if (ext === "txt") items = this.parseLines((await file.text()).split(/\r?\n/));
      else items = await this.parseSheet(file);

      // de-duplicate + cap
      const seen = new Set();
      items = items.filter((t) => {
        const k = t.title.toLowerCase();
        if (!t.title || seen.has(k)) return false;
        seen.add(k);
        return true;
      });
      if (!items.length) {
        return this.setStatus(
          ext === "pdf"
            ? "Couldn't find any text to turn into tasks. If this PDF is a scan or photo, it has no readable text — try a text-based PDF or Excel."
            : "Couldn't find any tasks in that file.",
          true
        );
      }
      let capped = false;
      if (items.length > this.MAX_TASKS) { items = items.slice(0, this.MAX_TASKS); capped = true; }
      this.rows = items.map((t) => ({ ...t, keep: !t.done }));
      this.renderPreview(file.name, capped);
    } catch (err) {
      console.error("[TaskImport]", err);
      this.setStatus(err?.message || "Something went wrong reading that file.", true);
    }
  },

  // ---------- parsing: spreadsheets ----------
  async parseSheet(file) {
    await this.loadScript(this.LIBS.xlsx);
    const buf = await file.arrayBuffer();
    const wb = window.XLSX.read(buf, { type: "array" });
    const out = [];
    for (const name of wb.SheetNames) {
      const ws = wb.Sheets[name];
      const rows = window.XLSX.utils.sheet_to_json(ws, { header: 1, raw: true, defval: "" });
      out.push(...this.parseTable(rows, wb.SheetNames.length > 1 ? name : ""));
    }
    return out;
  },

  parseTable(rows, sheetName) {
    rows = rows.filter((r) => r.some((c) => String(c).trim() !== ""));
    if (!rows.length) return [];

    const RE = {
      title: /^(task|tasks|to.?do|title|name|topic|topics|chapter|item|activity|work|assignment|action|goal)s?$/i,
      due: /(due|deadline|date|by when|target|submit)/i,
      prio: /(priorit|urgen|importan)/i,
      cat: /(categor|type)/i,
      notes: /(note|remark|comment|detail|description)/i,
      status: /(status|done|complete)/i,
      subj: /(subject|course|exam|class)/i,
    };

    // find the header row (first 10 rows) — one that has a title-like column
    let hi = -1, map = {};
    for (let i = 0; i < Math.min(rows.length, 10); i++) {
      const cells = rows[i].map((c) => String(c).trim());
      const titleCol = cells.findIndex((c) => RE.title.test(c));
      if (titleCol !== -1) {
        hi = i;
        map.title = titleCol;
        cells.forEach((c, idx) => {
          if (idx === titleCol) return;
          if (map.prio == null && RE.prio.test(c)) map.prio = idx;
          else if (map.status == null && RE.status.test(c)) map.status = idx;
          else if (map.cat == null && RE.cat.test(c)) map.cat = idx;
          else if (map.subj == null && RE.subj.test(c)) map.subj = idx;
          else if (map.due == null && RE.due.test(c)) map.due = idx;
          else if (map.notes == null && RE.notes.test(c)) map.notes = idx;
        });
        break;
      }
    }

    const out = [];
    const start = hi === -1 ? 0 : hi + 1;
    for (let i = start; i < rows.length; i++) {
      const r = rows[i];
      let title;
      if (hi === -1) {
        // no header: longest text cell in the row is the task
        const texts = r.map((c) => String(c).trim()).filter((c) => c && isNaN(Number(c)));
        title = texts.sort((a, b) => b.length - a.length)[0] || "";
      } else {
        title = String(r[map.title] ?? "").trim();
      }
      if (!title) continue;

      let due = null;
      if (map.due != null) due = this.cellToDate(r[map.due]);
      if (!due && hi === -1) for (const c of r) { due = this.cellToDate(c); if (due) break; }

      const prio = map.prio != null ? this.normPriority(r[map.prio]) : this.detectPriority(title).priority;
      const notesParts = [];
      if (map.notes != null && String(r[map.notes]).trim()) notesParts.push(String(r[map.notes]).trim());
      let goal_id = null;
      if (map.subj != null && String(r[map.subj]).trim()) {
        const sv = String(r[map.subj]).trim();
        const g = (typeof Goals !== "undefined" ? Goals.list : []).find((x) => !x.archived && x.name.toLowerCase() === sv.toLowerCase());
        if (g) goal_id = g.id; else notesParts.unshift(sv);
      }
      if (sheetName) notesParts.push(`Sheet: ${sheetName}`);

      let category = this.normCategory(map.cat != null ? r[map.cat] : "") || this.guessCategory(title + " " + notesParts.join(" "));
      let done = false;
      if (map.status != null) done = /^(done|complete[d]?|yes|y|true|1|✓|✔|x)$/i.test(String(r[map.status]).trim());

      out.push({ title: title.slice(0, 200), description: notesParts.join(" · "), due_date: due, priority: prio, category, goal_id, done });
    }
    return out;
  },

  // ---------- parsing: PDF ----------
  async parsePdf(file) {
    await this.loadScript(this.LIBS.pdf);
    const pdfjs = window.pdfjsLib;
    pdfjs.GlobalWorkerOptions.workerSrc = this.LIBS.pdfWorker;
    const doc = await pdfjs.getDocument({ data: await file.arrayBuffer() }).promise;
    const pages = Math.min(doc.numPages, this.MAX_PDF_PAGES);
    const lines = [];
    for (let p = 1; p <= pages; p++) {
      const page = await doc.getPage(p);
      const content = await page.getTextContent();
      // group text pieces into visual lines by their y position
      const buckets = [];
      for (const it of content.items) {
        if (!it.str || !it.str.trim()) continue;
        const y = it.transform[5], x = it.transform[4];
        let b = buckets.find((k) => Math.abs(k.y - y) < 3);
        if (!b) { b = { y, parts: [] }; buckets.push(b); }
        b.parts.push({ x, s: it.str, w: it.width || 0 });
      }
      buckets.sort((a, b) => b.y - a.y);
      for (const b of buckets) {
        b.parts.sort((a, c) => a.x - c.x);
        let text = "", prevEnd = null;
        for (const part of b.parts) {
          if (prevEnd !== null && part.x - prevEnd > 12) text += "   "; // wide gap = table column
          text += part.s;
          prevEnd = part.x + part.w;
        }
        lines.push(text.replace(/\s+$/g, ""));
      }
    }
    return this.parseLines(lines);
  },

  // ---------- parsing: plain lines (PDF text / .txt) ----------
  parseLines(rawLines) {
    const BULLET = /^\s*(?:[-–—•*▪◦○●□☐■▫✓✔☑►▶➤>·]|\[[ xX✓]?\]|\d{1,3}[.)]|\(?[a-zA-Z][.)]|\(\d{1,3}\))\s+/;
    const lines = rawLines.map((l) => l.replace(/\u00a0/g, " ").trimEnd()).filter((l) => l.trim());
    const marked = lines.filter((l) => BULLET.test(l)).length;
    const bulletMode = marked >= 3;

    const items = [];
    let section = "";
    for (const raw of lines) {
      let line = raw.trim();
      if (/^(page\s*)?\d+(\s*(of|\/)\s*\d+)?$/i.test(line)) continue; // page numbers
      if (line.length < 3) continue;

      const isBullet = BULLET.test(line);
      const wasDone = /^\s*(?:\[[xX✓]\]|[✓✔☑])/.test(line);
      const stripped = line.replace(BULLET, "").trim();

      // headings -> context for the tasks under them
      const looksHeading = !isBullet && (/[:：]$/.test(stripped) || (stripped.length < 60 && stripped === stripped.toUpperCase() && /[A-Z]{3}/.test(stripped)));
      if (looksHeading) { section = stripped.replace(/[:：]$/, ""); continue; }

      if (bulletMode && !isBullet) {
        // wrapped continuation of the previous bullet
        const prev = items[items.length - 1];
        if (prev && /^[a-z(]/.test(stripped) && prev.title.length < 160) { prev.title += " " + stripped; continue; }
        // a short standalone line without a full stop is probably a task too; long prose is skipped
        if (stripped.length > 100 || /[.!?]$/.test(stripped)) continue;
      }

      let text = stripped;
      const d = this.extractDate(text);
      text = d.text;
      const p = this.detectPriority(text);
      text = p.text.replace(/\s{2,}/g, " ").trim().replace(/\s+(by|on|before|due|till|until|from|at)$/i, "").replace(/^[-–—:|,\s]+|[-–—:|,\s]+$/g, "").trim();
      if (text.length < 3) continue;

      let description = section ? `Section: ${section}` : "";
      if (text.length > 160) { description = (description ? description + " · " : "") + text; text = text.slice(0, 157).trimEnd() + "…"; }
      items.push({
        title: text,
        description,
        due_date: d.date,
        priority: p.priority,
        category: this.guessCategory(text + " " + section),
        goal_id: null,
        done: wasDone,
      });
    }
    return items;
  },

  // ---------- helpers ----------
  MONTHS: { jan: 0, feb: 1, mar: 2, apr: 3, may: 4, jun: 5, jul: 6, aug: 7, sep: 8, sept: 8, oct: 9, nov: 10, dec: 11 },

  ymd(y, m, d) {
    if (y < 100) y += 2000;
    const dt = new Date(y, m, d);
    if (dt.getFullYear() !== y || dt.getMonth() !== m || dt.getDate() !== d) return null;
    return `${y}-${String(m + 1).padStart(2, "0")}-${String(d).padStart(2, "0")}`;
  },

  // a date with no year: assume this year, or next year if it's well in the past
  yearless(m, d) {
    const now = new Date();
    let y = now.getFullYear();
    const cand = new Date(y, m, d);
    if (cand < new Date(now.getFullYear(), now.getMonth(), now.getDate() - 60)) y += 1;
    return this.ymd(y, m, d);
  },

  extractDate(text) {
    let m;
    // 2026-10-12
    if ((m = text.match(/\b(20\d{2})[-/.](\d{1,2})[-/.](\d{1,2})\b/))) {
      const v = this.ymd(+m[1], +m[2] - 1, +m[3]);
      if (v) return { date: v, text: text.replace(m[0], " ") };
    }
    // 12/10/2026, 12-10-26 (day first — Indian format)
    if ((m = text.match(/\b(\d{1,2})[-/.](\d{1,2})[-/.](\d{2}|\d{4})\b/))) {
      const v = this.ymd(+m[3], +m[2] - 1, +m[1]);
      if (v) return { date: v, text: text.replace(m[0], " ") };
    }
    // 12 Oct 2026 / 12th October / 12 Oct
    if ((m = text.match(/\b(\d{1,2})(?:st|nd|rd|th)?[\s-]+(jan|feb|mar|apr|may|jun|jul|aug|sept?|oct|nov|dec)[a-z]*\.?(?:,?\s+(\d{4}))?\b/i))) {
      const mo = this.MONTHS[m[2].toLowerCase()];
      const v = m[3] ? this.ymd(+m[3], mo, +m[1]) : this.yearless(mo, +m[1]);
      if (v) return { date: v, text: text.replace(m[0], " ") };
    }
    // Oct 12 / October 12, 2026
    if ((m = text.match(/\b(jan|feb|mar|apr|may|jun|jul|aug|sept?|oct|nov|dec)[a-z]*\.?\s+(\d{1,2})(?:st|nd|rd|th)?(?:,?\s+(\d{4}))?\b/i))) {
      const mo = this.MONTHS[m[1].toLowerCase()];
      const v = m[3] ? this.ymd(+m[3], mo, +m[2]) : this.yearless(mo, +m[2]);
      if (v) return { date: v, text: text.replace(m[0], " ") };
    }
    return { date: null, text };
  },

  cellToDate(v) {
    if (v === "" || v == null) return null;
    if (v instanceof Date) return localDateStr(v);
    if (typeof v === "number") {
      if (v > 20000 && v < 80000) { // Excel serial date -> exact day, no timezone drift
        const dt = new Date(Math.round((v - 25569) * 86400000));
        return this.ymd(dt.getUTCFullYear(), dt.getUTCMonth(), dt.getUTCDate());
      }
      return null;
    }
    const s = String(v).trim();
    const r = this.extractDate(s);
    return r.date;
  },

  normPriority(v) {
    const s = String(v ?? "").trim().toLowerCase();
    if (!s) return "medium";
    if (/^(h|1|urgent|high|critical|imp)/.test(s)) return "high";
    if (/^(l|3|low|optional|minor)/.test(s)) return "low";
    return "medium";
  },

  normCategory(v) {
    const s = String(v ?? "").trim().toLowerCase();
    if (/(academ|study|college|school|exam|class)/.test(s)) return "academic";
    if (/(fit|gym|workout|health|sport)/.test(s)) return "fitness";
    if (/personal|home|other|general/.test(s)) return "personal";
    return "";
  },

  detectPriority(text) {
    let priority = "medium", out = text;
    if (/\b(urgent|asap|high priority|priority:\s*high|!!+)/i.test(text) || /\((high)\)/i.test(text)) {
      priority = "high";
      out = out.replace(/\b(urgent|asap|high priority|priority:\s*high)\b|!!+|\((high)\)/gi, " ");
    } else if (/\b(low priority|priority:\s*low|optional|someday)\b/i.test(text) || /\((low)\)/i.test(text)) {
      priority = "low";
      out = out.replace(/\b(low priority|priority:\s*low)\b|\((low)\)/gi, " ");
    } else if (/\(medium\)|priority:\s*medium/i.test(text)) {
      out = out.replace(/\(medium\)|priority:\s*medium/gi, " ");
    }
    return { priority, text: out };
  },

  guessCategory(text) {
    const t = text.toLowerCase();
    if (/\b(gym|workout|run|running|exercise|diet|yoga|cardio|squat|pushup|push-up|steps|protein|stretch)/.test(t)) return "fitness";
    if (/\b(study|chapter|revise|revision|solve|practice|assignment|exam|test|mock|lecture|read|notes|submit|project|lab|homework|syllabus|unit|module|paper|quiz|class|topic|formula|ncert|dsa|code)/.test(t)) return "academic";
    return "personal";
  },

  // ---------- step 2: preview + edit ----------
  renderPreview(fileName, capped) {
    const goals = (typeof Goals !== "undefined" ? Goals.list : []).filter((g) => !g.archived);
    openModal(`
      <h3>Review your tasks</h3>
      <p class="muted" style="font-size:12px;margin:0 0 10px"><b id="imp-count"></b> from <i>${escapeHtml(fileName)}</i>${capped ? ` — showing the first ${this.MAX_TASKS}` : ""}. Edit or untick anything you don't want.</p>
      <div class="imp-tools">
        <button type="button" class="link-btn" id="imp-all">Select all</button>
        <button type="button" class="link-btn" id="imp-none">None</button>
        <label class="imp-goal">Goal for all
          <select id="imp-goal"><option value="">—</option>${goals.map((g) => `<option value="${g.id}">${escapeHtml(g.name)}</option>`).join("")}</select>
        </label>
      </div>
      <div class="imp-list" id="imp-list"></div>
      <div class="modal-actions">
        <button type="button" class="btn btn-ghost" id="imp-back">Back</button>
        <button type="button" class="btn btn-primary" id="imp-save"></button>
      </div>
    `);
    const modal = document.querySelector("#modal-root .modal-card");
    if (modal) modal.classList.add("imp-wide");

    const list = document.getElementById("imp-list");
    list.innerHTML = this.rows
      .map(
        (t, i) => `
      <div class="imp-row ${t.keep ? "" : "off"}" data-i="${i}">
        <input type="checkbox" class="imp-keep" ${t.keep ? "checked" : ""} aria-label="Include this task" />
        <input type="text" class="imp-title" value="${escapeHtml(t.title)}" maxlength="200" />
        <input type="date" class="imp-due" value="${t.due_date || ""}" />
        <select class="imp-prio">
          ${["high", "medium", "low"].map((p) => `<option value="${p}" ${t.priority === p ? "selected" : ""}>${p[0].toUpperCase() + p.slice(1)}</option>`).join("")}
        </select>
      </div>`
      )
      .join("");

    list.addEventListener("input", (e) => {
      const row = e.target.closest(".imp-row");
      if (!row) return;
      const t = this.rows[+row.dataset.i];
      if (e.target.classList.contains("imp-title")) t.title = e.target.value;
      if (e.target.classList.contains("imp-due")) t.due_date = e.target.value || null;
    });
    list.addEventListener("change", (e) => {
      const row = e.target.closest(".imp-row");
      if (!row) return;
      const t = this.rows[+row.dataset.i];
      if (e.target.classList.contains("imp-keep")) { t.keep = e.target.checked; row.classList.toggle("off", !t.keep); this.updateCount(); }
      if (e.target.classList.contains("imp-prio")) t.priority = e.target.value;
    });

    const setAll = (v) => {
      this.rows.forEach((t) => (t.keep = v));
      list.querySelectorAll(".imp-row").forEach((r) => {
        r.classList.toggle("off", !v);
        r.querySelector(".imp-keep").checked = v;
      });
      this.updateCount();
    };
    document.getElementById("imp-all").onclick = () => setAll(true);
    document.getElementById("imp-none").onclick = () => setAll(false);
    document.getElementById("imp-back").onclick = () => this.open();
    document.getElementById("imp-save").onclick = () => this.save();
    this.updateCount();
  },

  updateCount() {
    const n = this.rows.filter((t) => t.keep && t.title.trim()).length;
    const c = document.getElementById("imp-count");
    const b = document.getElementById("imp-save");
    if (c) c.textContent = `${this.rows.length} task${this.rows.length === 1 ? "" : "s"} found`;
    if (b) { b.textContent = n ? `Add ${n} task${n === 1 ? "" : "s"}` : "Nothing selected"; b.disabled = !n; }
  },

  // ---------- step 3: save ----------
  async save() {
    const btn = document.getElementById("imp-save");
    const chosen = this.rows.filter((t) => t.keep && t.title.trim());
    if (!chosen.length) return;
    btn.disabled = true;
    btn.textContent = "Saving…";
    try {
      const user = await DB.currentUser();
      if (!user) throw new Error("Please log in again.");
      const allGoal = document.getElementById("imp-goal")?.value || null;
      const payload = chosen.map((t) => ({
        user_id: user.id,
        title: t.title.trim().slice(0, 200),
        description: t.description || null,
        category: ["academic", "fitness", "personal"].includes(t.category) ? t.category : "personal",
        priority: ["high", "medium", "low"].includes(t.priority) ? t.priority : "medium",
        goal_id: t.goal_id || allGoal || null,
        due_date: t.due_date || null,
        status: "pending",
      }));
      for (let i = 0; i < payload.length; i += 100) {
        const { error } = await supabaseClient.from("tasks").insert(payload.slice(i, i + 100));
        if (error) throw error;
      }
      DB._invalidate("tasks");
      closeModal();
      toast(`${payload.length} task${payload.length === 1 ? "" : "s"} added to your list.`);
      Tasks.render();
    } catch (err) {
      console.error("[TaskImport save]", err);
      toast(err?.message || "Couldn't save the tasks.", "error");
      btn.disabled = false;
      this.updateCount();
    }
  },
};

// ---- js/milestones.js ----
// ============================================================
// MILESTONES — deadline + progress tracking, optionally linked to a Goal
// ============================================================

const Milestones = {
  list: [],
  activeFilter: "active",

  async load() {
    const user = await DB.currentUser();
    if (!user) return;
    this.list = await DB.list("milestones", { filters: { user_id: user.id }, order: "deadline", ascending: true });
  },

  async render() {
    await Goals.load();
    await this.load();
    const el = document.getElementById("page-milestones");
    el.innerHTML = `
      <div class="page-header">
        <h2>Milestones</h2>
        <button class="btn btn-primary" id="add-milestone-btn">+ Add Milestone</button>
      </div>
      <div class="tabs" id="milestone-filters">
        ${["active", "completed", "academic", "fitness", "personal", "all"]
          .map((f) => `<button class="tab ${f === this.activeFilter ? "active" : ""}" data-filter="${f}">${f[0].toUpperCase() + f.slice(1)}</button>`)
          .join("")}
      </div>
      <div id="milestone-grid" class="milestone-grid"></div>
    `;
    document.getElementById("add-milestone-btn").onclick = () => this.openForm();
    document.querySelectorAll("#milestone-filters .tab").forEach((t) => {
      t.onclick = () => {
        document.querySelectorAll("#milestone-filters .tab").forEach((x) => x.classList.remove("active"));
        t.classList.add("active");
        this.activeFilter = t.dataset.filter;
        this.renderGrid();
      };
    });
    this.renderGrid();
  },

  filtered() {
    switch (this.activeFilter) {
      case "active":
        return this.list.filter((m) => m.status !== "completed" && m.status !== "archived");
      case "completed":
        return this.list.filter((m) => m.status === "completed");
      case "academic":
      case "fitness":
      case "personal":
        return this.list.filter((m) => m.category === this.activeFilter);
      default:
        return this.list.filter((m) => m.status !== "archived");
    }
  },

  renderGrid() {
    const el = document.getElementById("milestone-grid");
    const list = this.filtered();
    if (!list.length) {
      el.innerHTML = `<p class="empty-state">Nothing here yet — set a milestone and watch the ring fill up.</p>`;
      return;
    }
    const today = todayStr();
    el.innerHTML = list
      .map((m) => {
        const goal = Goals.list.find((g) => g.id === m.goal_id);
        const overdue = m.deadline && m.deadline < today && m.status !== "completed";
        const circumference = 2 * Math.PI * 21;
        const offset = circumference - (Math.min(100, Math.max(0, m.progress || 0)) / 100) * circumference;
        return `
        <div class="milestone-card" data-id="${m.id}">
          <div class="milestone-top">
            <div>
              <div class="milestone-title">${escapeHtml(m.title)}</div>
              ${m.description ? `<div class="milestone-desc">${escapeHtml(m.description)}</div>` : ""}
            </div>
            <span class="milestone-badge ${escapeHtml(m.category || "personal")}">${escapeHtml(m.category || "personal")}</span>
          </div>

          <div class="milestone-ring-row">
            <div class="milestone-ring-wrap">
              <svg class="milestone-ring" viewBox="0 0 48 48">
                <circle class="milestone-ring-bg" cx="24" cy="24" r="21"></circle>
                <circle class="milestone-ring-fill" cx="24" cy="24" r="21"
                  stroke-dasharray="${circumference}" stroke-dashoffset="${offset}"></circle>
              </svg>
              <span class="milestone-ring-pct">${m.progress || 0}%</span>
            </div>
            <div class="milestone-meta">
              ${goal ? `<span>🎯 ${escapeHtml(goal.name)}</span>` : ""}
              ${m.deadline ? `<span class="milestone-deadline ${overdue ? "overdue" : ""}">${overdue ? "Overdue · " : "Due "}${fmtDate(m.deadline)}</span>` : `<span>No deadline</span>`}
              <span class="milestone-status ${m.status}">${m.status.replace("_", " ")}</span>
            </div>
          </div>

          <div class="milestone-progress-row">
            <input type="range" min="0" max="100" step="5" value="${m.progress || 0}" data-id="${m.id}" class="milestone-slider" ${m.status === "completed" ? "disabled" : ""} />
          </div>

          <div class="milestone-actions">
            <button class="link-btn" data-action="edit" data-id="${m.id}">Edit</button>
            <button class="link-btn danger" data-action="delete" data-id="${m.id}">Delete</button>
          </div>
        </div>`;
      })
      .join("");

    el.querySelectorAll(".milestone-slider").forEach((slider) => {
      slider.addEventListener("input", (e) => {
        const card = e.target.closest(".milestone-card");
        card.querySelector(".milestone-ring-pct").textContent = `${e.target.value}%`;
        const circumference = 2 * Math.PI * 21;
        const offset = circumference - (e.target.value / 100) * circumference;
        card.querySelector(".milestone-ring-fill").style.strokeDashoffset = offset;
      });
      slider.addEventListener("change", (e) => this.updateProgress(e.target.dataset.id, Number(e.target.value)));
    });
    el.querySelectorAll("[data-action]").forEach((btn) => {
      btn.addEventListener("click", () => {
        const m = this.list.find((x) => x.id === btn.dataset.id);
        if (btn.dataset.action === "edit") this.openForm(m);
        if (btn.dataset.action === "delete") this.deleteFlow(m);
      });
    });
  },

  async updateProgress(id, progress) {
    const m = this.list.find((x) => x.id === id);
    if (!m) return;
    const wasCompleted = m.status === "completed";
    const status = progress >= 100 ? "completed" : progress > 0 ? "in_progress" : "not_started";
    await DB.update("milestones", id, { progress, status, updated_at: new Date().toISOString() });

    if (status === "completed" && !wasCompleted) {
      if (await alreadyRewarded("milestone_complete", id)) toast("Milestone complete.");
      else {
        const xp = await DB.reward("xp_weekly_milestone", 75, "milestone_complete", "milestone", `Completed milestone "${m.title}"`, id);
        toast(`🎉 Milestone complete — +${xp} XP`);
      }
    } else {
      toast("Progress updated.");
    }
    this.render();
  },

  openForm(m = null) {
    const activeGoals = Goals.list.filter((g) => !g.archived);
    openModal(`
      <h3>${m ? "Edit Milestone" : "Add Milestone"}</h3>
      <form id="milestone-form" class="grid-form">
        <label class="full">Title<input required id="ms-title" value="${m ? escapeHtml(m.title) : ""}" /></label>
        <label class="full">Description<textarea id="ms-desc">${m ? escapeHtml(m.description || "") : ""}</textarea></label>
        <label>Category
          <select id="ms-category">
            <option value="academic" ${m?.category === "academic" ? "selected" : ""}>Academic</option>
            <option value="fitness" ${m?.category === "fitness" ? "selected" : ""}>Fitness</option>
            <option value="personal" ${!m || m?.category === "personal" ? "selected" : ""}>Personal</option>
          </select>
        </label>
        <label>Goal (optional)
          <select id="ms-goal">
            <option value="">—</option>
            ${activeGoals.map((g) => `<option value="${g.id}" ${m?.goal_id === g.id ? "selected" : ""}>${escapeHtml(g.name)}</option>`).join("")}
          </select>
        </label>
        <label>Deadline<input type="date" id="ms-deadline" value="${m?.deadline || ""}" /></label>
        <label>Progress (%)<input type="number" min="0" max="100" step="5" id="ms-progress" value="${m?.progress ?? 0}" /></label>
        <div class="modal-actions full">
          <button type="button" class="btn btn-ghost" id="ms-cancel">Cancel</button>
          <button type="submit" class="btn btn-primary">Save</button>
        </div>
      </form>
    `);
    document.getElementById("ms-cancel").onclick = closeModal;
    document.getElementById("milestone-form").onsubmit = async (e) => {
      e.preventDefault();
      const progress = Math.min(100, Math.max(0, Number(document.getElementById("ms-progress").value) || 0));
      const payload = {
        title: document.getElementById("ms-title").value.trim(),
        description: document.getElementById("ms-desc").value.trim(),
        category: document.getElementById("ms-category").value,
        goal_id: document.getElementById("ms-goal").value || null,
        deadline: document.getElementById("ms-deadline").value || null,
        progress,
        status: progress >= 100 ? "completed" : progress > 0 ? "in_progress" : "not_started",
      };
      if (!payload.title) return;

      const wasCompleted = m?.status === "completed";
      let saved;
      if (m) saved = await DB.update("milestones", m.id, { ...payload, updated_at: new Date().toISOString() });
      else saved = await DB.insert("milestones", payload);

      if (payload.status === "completed" && !wasCompleted) {
        const refId = saved?.id || m?.id || null;
        if (!(await alreadyRewarded("milestone_complete", refId)))
          await DB.reward("xp_weekly_milestone", 75, "milestone_complete", "milestone", `Completed milestone "${payload.title}"`, refId);
      }

      closeModal();
      toast(m ? "Milestone updated." : "Milestone added.");
      this.render();
    };
  },

  async deleteFlow(m) {
    const ok = await confirmDialog("Delete this milestone?", "This can't be undone.", "Delete");
    if (!ok) return;
    await DB.remove("milestones", m.id);
    toast("Milestone deleted.");
    this.render();
  },
};

// ---- js/fitness.js ----
// ============================================================
// FITNESS — workout log (date + exercises with sets/reps/weight),
// optional templates (Push/Pull/Legs/custom), auto-detected PRs,
// and body measurements with a progression chart.
// ============================================================

const Fitness = {
  activeTab: "workouts",
  workouts: [],
  templates: [],
  measurements: [],

  async render() {
    this.wiz = null;
    const el = document.getElementById("page-fitness");
    el.innerHTML = `
      <div class="page-header">
        <h2>Fitness</h2>
        <div class="header-actions">
          <button class="btn btn-ghost" id="add-template-btn">+ Template</button>
          <button class="btn btn-primary" id="add-workout-btn">+ Add Workout</button>
        </div>
      </div>
      <div class="tabs" id="fitness-tabs">
        <button class="tab ${this.activeTab === "workouts" ? "active" : ""}" data-tab="workouts">Workouts</button>
        <button class="tab ${this.activeTab === "prs" ? "active" : ""}" data-tab="prs">Personal Records</button>
        <button class="tab ${this.activeTab === "measurements" ? "active" : ""}" data-tab="measurements">Body Measurements</button>
      </div>
      <div id="fitness-body"></div>
    `;
    document.getElementById("add-workout-btn").onclick = () => this.openWorkoutForm();
    document.getElementById("add-template-btn").onclick = () => this.openTemplateForm();
    document.querySelectorAll("#fitness-tabs .tab").forEach((t) => {
      t.onclick = () => {
        this.activeTab = t.dataset.tab;
        this.render();
      };
    });
    if (this.activeTab === "workouts") await this.renderWorkouts();
    else if (this.activeTab === "prs") await this.renderPRs();
    else await this.renderMeasurements();
  },

  async loadWorkouts() {
    const user = await DB.currentUser();
    // 3 requests in total, however many workouts there are
    // (it used to make one extra request PER workout)
    const [workouts, templates, exercises] = await Promise.all([
      DB.list("workouts", { filters: { user_id: user.id }, order: "workout_date", ascending: false, limit: 60 }),
      DB.list("workout_templates", { filters: { user_id: user.id } }),
      DB.list("workout_exercises", { filters: { user_id: user.id } }),
    ]);
    this.templates = templates;
    const byWorkout = {};
    exercises.forEach((ex) => (byWorkout[ex.workout_id] = byWorkout[ex.workout_id] || []).push(ex));
    this.workouts = workouts.map((w) => ({ ...w, exercises: byWorkout[w.id] || [] }));
  },

  async renderWorkouts() {
    await this.loadWorkouts();
    const body = document.getElementById("fitness-body");
    if (!this.workouts.length) {
      body.innerHTML = `<p class="empty-state">No workouts logged yet.</p>`;
      return;
    }
    body.innerHTML = this.workouts
      .map(
        (w) => `
      <div class="panel workout-card">
        <div class="page-header" style="margin-bottom:8px;">
          <h3>${escapeHtml(w.workout_type || "Workout")} <span class="muted small">· ${fmtDate(w.workout_date)}</span></h3>
          <div class="record-actions">
            <button class="link-btn" data-action="edit-w" data-id="${w.id}">Edit</button>
            <button class="link-btn danger" data-action="del-w" data-id="${w.id}">Delete</button>
          </div>
        </div>
        ${w.exercises.length
          ? w.exercises.map((ex) => `<div class="mini-row"><span>${escapeHtml(ex.exercise_name)}${ex.is_pr ? " 🏆" : ""}</span><span class="muted">${ex.sets || "?"}×${ex.reps || "?"} @ ${ex.weight || "?"}${ex.weight_unit || "kg"}</span></div>`).join("")
          : `<p class="empty-state">No exercises logged.</p>`}
        ${w.notes ? `<p class="muted small" style="margin-top:8px;">${escapeHtml(w.notes)}</p>` : ""}
      </div>`
      )
      .join("");

    body.querySelectorAll("[data-action='del-w']").forEach((btn) => {
      btn.onclick = async () => {
        const ok = await confirmDialog("Delete this workout?", "This removes it and its exercises from your log and PR history.", "Delete");
        if (!ok) return;
        await DB.remove("workouts", btn.dataset.id);
        toast("Workout deleted.");
        this.render();
      };
    });
    body.querySelectorAll("[data-action='edit-w']").forEach((btn) => {
      btn.onclick = () => {
        const w = this.workouts.find((x) => x.id === btn.dataset.id);
        this.openWorkoutForm(w);
      };
    });
  },

  openTemplateForm() {
    const existing = this.templates || [];
    openModal(`
      <h3>Workout Templates</h3>
      <p class="modal-body-text">Templates are the workout types you can pick when logging a workout.</p>
      ${existing.length ? `<div class="topic-list">${existing.map((t) => `<div class="topic-row"><span>${escapeHtml(t.name)}</span><button type="button" class="link-btn danger" data-del-tpl="${t.id}">Delete</button></div>`).join("")}</div>` : ""}
      <form id="template-form">
        <label>New template<input required id="tpl-name" placeholder="Push, Pull, Legs, Upper, Lower, custom..." /></label>
        <div class="modal-actions">
          <button type="button" class="btn btn-ghost" id="tpl-cancel">Close</button>
          <button type="submit" class="btn btn-primary">Add</button>
        </div>
      </form>
    `);
    document.getElementById("tpl-cancel").onclick = closeModal;
    document.querySelectorAll("[data-del-tpl]").forEach((b) => {
      b.onclick = async () => {
        await DB.remove("workout_templates", b.dataset.delTpl);
        this.templates = this.templates.filter((t) => t.id !== b.dataset.delTpl);
        toast("Template deleted.");
        this.openTemplateForm();
      };
    });
    document.getElementById("template-form").onsubmit = async (e) => {
      e.preventDefault();
      const name = document.getElementById("tpl-name").value.trim();
      if (!name) return;
      const saved = await DB.insert("workout_templates", { name });
      this.templates = [...(this.templates || []), saved];
      toast("Template added.");
      this.openTemplateForm();
    };
  },

  // built-in workout types + the person's own templates (no duplicates)
  typeOptions(current) {
    const seen = new Set(), out = [];
    const add = (name, group) => { const k = name.toLowerCase(); if (seen.has(k)) return; seen.add(k); out.push({ name, group }); };
    (this.templates || []).forEach((t) => add(t.name, "Your templates"));
    if (current) add(current, "Your templates");
    WORKOUT_TYPES.forEach(([group, names]) => names.forEach((n) => add(n, group)));
    const groups = [];
    out.forEach((o) => { let g = groups.find((x) => x.name === o.group); if (!g) groups.push((g = { name: o.group, items: [] })); g.items.push(o.name); });
    return groups.map((g) => `<optgroup label="${escapeHtml(g.name)}">${g.items.map((n) => `<option value="${escapeHtml(n)}"${n === current ? " selected" : ""}>${escapeHtml(n)}</option>`).join("")}</optgroup>`).join("");
  },

  openWorkoutForm(workout = null) {
    const exercises = workout?.exercises || [{ exercise_name: "", sets: "", reps: "", weight: "" }];
    openModal(`
      <h3>${workout ? "Edit Workout" : "Add Workout"}</h3>
      <form id="workout-form">
        <label>Date<input type="date" id="w-date" value="${workout?.workout_date || todayStr()}" /></label>
        <label>Type<select id="w-type">
          <option value="">Select a workout type</option>
          ${this.typeOptions(workout?.workout_type)}
        </select></label>
        <div id="exercise-rows"></div>
        <button type="button" class="link-btn" id="add-exercise-row">+ Add exercise</button>
        <label>Notes<textarea id="w-notes">${workout ? escapeHtml(workout.notes || "") : ""}</textarea></label>
        <div class="modal-actions">
          <button type="button" class="btn btn-ghost" id="w-cancel">Cancel</button>
          <button type="submit" class="btn btn-primary">Save</button>
        </div>
      </form>
    `);

    const rowsEl = document.getElementById("exercise-rows");
    const addRow = (ex = { exercise_name: "", sets: "", reps: "", weight: "" }) => {
      const row = document.createElement("div");
      row.className = "exercise-row";
      row.innerHTML = `
        <input placeholder="Exercise" class="ex-name" value="${escapeHtml(ex.exercise_name || "")}" />
        <input placeholder="Sets" type="number" class="ex-sets" value="${ex.sets ?? ""}" />
        <input placeholder="Reps" type="number" class="ex-reps" value="${ex.reps ?? ""}" />
        <input placeholder="Weight (kg)" type="number" class="ex-weight" value="${ex.weight ?? ""}" />
        <button type="button" class="link-btn danger ex-remove">✕</button>
      `;
      row.querySelector(".ex-remove").onclick = () => row.remove();
      rowsEl.appendChild(row);
    };
    exercises.forEach((ex) => addRow(ex));
    document.getElementById("add-exercise-row").onclick = () => addRow();
    document.getElementById("w-cancel").onclick = closeModal;

    document.getElementById("workout-form").onsubmit = async (e) => {
      e.preventDefault();
      const payload = {
        workout_date: document.getElementById("w-date").value,
        workout_type: document.getElementById("w-type").value || null,
        notes: document.getElementById("w-notes").value.trim(),
      };
      let savedWorkout;
      if (workout) {
        savedWorkout = await DB.update("workouts", workout.id, payload);
        const existing = await DB.list("workout_exercises", { filters: { workout_id: workout.id } });
        for (const ex of existing) await DB.remove("workout_exercises", ex.id);
      } else {
        savedWorkout = await DB.insert("workouts", payload);
      }

      const rows = [...rowsEl.querySelectorAll(".exercise-row")];
      for (const row of rows) {
        const name = row.querySelector(".ex-name").value.trim();
        if (!name) continue;
        const weight = row.querySelector(".ex-weight").value;
        const isPR = await this.checkAndMarkPR(name, weight ? Number(weight) : null);
        await DB.insert("workout_exercises", {
          workout_id: savedWorkout.id,
          exercise_name: name,
          sets: numOrNullEl(row.querySelector(".ex-sets")),
          reps: numOrNullEl(row.querySelector(".ex-reps")),
          weight: weight ? Number(weight) : null,
          is_pr: isPR,
        });
      }

      if (!workout) {
        await DB.reward("xp_workout", 20, "workout", "workout", `Logged a ${payload.workout_type || "workout"}`, savedWorkout.id);
      }
      closeModal();
      toast("Workout saved.");
      this.render();
    };
  },

  // a PR = heaviest weight ever recorded for that exact exercise name (case-insensitive)
  async checkAndMarkPR(exerciseName, weight) {
    if (!weight) return false;
    const user = await DB.currentUser();
    const { data } = await DB.client
      .from("workout_exercises")
      .select("weight, exercise_name")
      .eq("user_id", user.id)
      .ilike("exercise_name", exerciseName.replace(/[\\%_]/g, (c) => "\\" + c));
    const maxPrev = Math.max(0, ...(data || []).map((r) => r.weight || 0));
    return weight > maxPrev;
  },

  async renderPRs() {
    const body = document.getElementById("fitness-body");
    const user = await DB.currentUser();
    const { data } = await DB.client
      .from("workout_exercises")
      .select("exercise_name, weight, weight_unit")
      .eq("user_id", user.id)
      .eq("is_pr", true)
      .order("weight", { ascending: false });

    if (!data || !data.length) {
      body.innerHTML = `<p class="empty-state">No personal records yet — they're detected automatically the first time you beat your previous best on an exercise.</p>`;
      return;
    }
    // keep only the current (highest) PR per exercise name
    const best = {};
    data.forEach((r) => {
      const key = r.exercise_name.toLowerCase();
      if (!best[key] || r.weight > best[key].weight) best[key] = r;
    });
    body.innerHTML = `<div class="stat-cards">${Object.values(best)
      .map((r) => `<div class="stat-card"><span class="stat-label">${escapeHtml(r.exercise_name)}</span><span class="stat-value">${r.weight}${r.weight_unit || "kg"}</span></div>`)
      .join("")}</div>`;
  },

  async renderMeasurements() {
    const body = document.getElementById("fitness-body");
    body.innerHTML = `
      <div class="page-header" style="margin-bottom:10px;">
        <span class="muted small">Tap a body part to measure just that, or start a guided walk-through.</span>
        <button class="btn btn-secondary" id="add-measurement-btn">+ Log Measurement</button>
      </div>
      <div class="meas-grid">
        <div class="panel meas-panel" id="body-panel"><h3>Body map</h3><div id="body-map"></div><div id="meas-wizard"></div></div>
        <div class="panel meas-panel" id="scale-panel"><h3>Body weight</h3><div id="weigh-scale"></div></div>
      </div>
      <div id="measurement-list" class="record-list"></div>
    `;
    document.getElementById("add-measurement-btn").onclick = () => this.startWizard();

    const user = await DB.currentUser();
    this.measurements = await DB.list("body_measurements", { filters: { user_id: user.id }, order: "measured_at", ascending: true });
    this.gender = await BodyGender.get(user);
    this.renderBodyMap();
    this.renderScale();
    this.renderWizard();

    const listEl = document.getElementById("measurement-list");
    if (!listEl) return;
    listEl.innerHTML = [...this.measurements].reverse()
      .map((m) => {
        const bits = BODY_PARTS.filter((p) => m[p.key] != null).map((p) => `${p.label} ${m[p.key]}`);
        return `<div class="record-card">
          <div class="record-main"><strong>${fmtDate(m.measured_at)}</strong><span class="muted">${m.weight != null ? m.weight + "kg" : ""}${bits.length ? (m.weight != null ? " · " : "") + bits.join(" · ") : ""}</span></div>
          <div class="record-actions"><button class="link-btn danger" data-id="${m.id}">Delete</button></div>
        </div>`;
      })
      .join("") || `<p class="empty-state">No measurements yet.</p>`;
    listEl.querySelectorAll("[data-id]").forEach((btn) => {
      btn.onclick = async () => {
        await DB.remove("body_measurements", btn.dataset.id);
        toast("Measurement deleted.");
        this.renderMeasurements();
      };
    });
  },

  // newest value that isn't empty, plus the one before it
  latestOf(key) {
    const rows = (this.measurements || []).filter((m) => m[key] != null);
    return { now: rows[rows.length - 1] || null, prev: rows[rows.length - 2] || null };
  },

  // ---- three-view, clay-mannequin body (front · side · back) ----
  // Shapes are drawn for one half and mirrored; soft gradients give the
  // rounded, sculpted "3D render" look. Measured parts tint in the accent
  // colour, and the part being asked about blinks red.
  renderBodyMap() {
    const el = document.getElementById("body-map");
    if (!el) return;
    const v = {};
    BODY_PARTS.forEach((p) => (v[p.key] = this.wiz?.vals?.[p.key] ?? this.latestOf(p.key).now?.[p.key] ?? null));
    const ask = this.wiz ? this.wiz.steps[this.wiz.i] : null;

    const chips = BODY_PARTS.map((p) => {
      const has = v[p.key] != null;
      return `<button type="button" class="bchip-btn${has ? " has" : ""}${ask === p.key ? " ask" : ""}" data-part="${p.key}"><span>${p.label}</span><b>${has ? v[p.key] + " cm" : "+ add"}</b></button>`;
    }).join("");

    const wire = (root) => root.querySelectorAll("[data-part]").forEach((n) => {
      const open = () => { if (!this.wiz) this.startWizard([n.dataset.part]); else this.gotoWizardPart(n.dataset.part); };
      n.addEventListener("click", open);
      n.addEventListener("keydown", (e) => { if (e.key === "Enter" || e.key === " ") { e.preventDefault(); open(); } });
    });
    // gender first: the mesh (and where the rings sit) depends on it
    if (!this.gender) {
      this._b3d?.dispose(); this._b3d = null;
      el.innerHTML = `<div class="gender-pick"><h4>First, pick the body type</h4><p class="muted small">Michi shows a matching 3D body, so your measurements land in the right place. You can change it any time.</p>
        <div class="gender-btns"><button type="button" class="gender-btn" data-g="male"><span>♂</span>Male</button><button type="button" class="gender-btn" data-g="female"><span>♀</span>Female</button></div></div>`;
      el.querySelectorAll("[data-g]").forEach((b) => (b.onclick = async () => { this.gender = b.dataset.g; await BodyGender.set(await DB.currentUser(), this.gender); this.renderBodyMap(); }));
      return;
    }
    const host3d = el.querySelector("#body3d");
    if (host3d && this._b3d && host3d.isConnected) {                 // already mounted: just refresh rings + chips
      el.querySelector("#body-chips").innerHTML = chips; wire(el.querySelector("#body-chips")); this._b3d.update(v, ask); return;
    }
    el.innerHTML = `<div id="body3d" class="body3d"></div>
      <p class="muted small body3d-help">Drag to turn the body · tap a ring or a body part to measure it · <button type="button" class="link-btn" id="gender-change">${this.gender === "male" ? "Male" : "Female"} (change)</button></p>
      <div class="bchips" id="body-chips">${chips}</div>
      <p class="idc-credit">3D bodies (simplified): <a href="https://sketchfab.com/3d-models/female-body-base-mesh-4bd94f4c0406464c91fdf55db6ca8d18" target="_blank" rel="noopener">Female body base mesh</a> by gus_thewise · <a href="https://sketchfab.com/3d-models/male-body-base-mesh-highpoly-9311f4f8fa1a4fe4bb0027ff7e8fd795" target="_blank" rel="noopener">Male body base mesh</a> by Mandrake · <a href="http://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noopener">CC BY 4.0</a></p>`;
    wire(el);
    el.querySelector("#gender-change").onclick = async () => { this.gender = this.gender === "male" ? "female" : "male"; await BodyGender.set(await DB.currentUser(), this.gender); this._b3d?.setGender(this.gender); el.querySelector("#gender-change").textContent = `${this.gender === "male" ? "Male" : "Female"} (change)`; };
    const mountIt = () => { this._b3d?.dispose(); this._b3d = window.Body3D.mount(el.querySelector("#body3d"), { gender: this.gender, values: v, ask, onPick: (k) => { if (!this.wiz) this.startWizard([k]); else this.gotoWizardPart(k); } }); };
    if (window.Body3D) mountIt(); else document.addEventListener("body3d-ready", mountIt, { once: true });
  },

  // ---- weighing scale: the needle is a real spring, the number follows it ----
  renderScale() {
    const el = document.getElementById("weigh-scale");
    if (!el) return;
    cancelAnimationFrame(this._scaleRaf);
    const { now, prev } = this.latestOf("weight");
    const W = now ? Number(now.weight) : 0, MAX = 150;
    const ang = (w) => -120 + (Math.min(Math.max(w, 0), MAX) / MAX) * 240;
    const pt = (deg, r) => [120 + r * Math.sin((deg * Math.PI) / 180), 92 - r * Math.cos((deg * Math.PI) / 180)];
    const ticks = Array.from({ length: 76 }, (_, i) => {
      const d = -120 + i * 3.2, major = i % 5 === 0, [x1, y1] = pt(d, 54), [x2, y2] = pt(d, major ? 46 : 50);
      return `<line x1="${x1.toFixed(1)}" y1="${y1.toFixed(1)}" x2="${x2.toFixed(1)}" y2="${y2.toFixed(1)}" class="st${major ? " big" : ""}"/>`;
    }).join("");
    const nums = Array.from({ length: 6 }, (_, i) => { const [tx, ty] = pt(-120 + i * 48, 37); return `<text x="${tx.toFixed(1)}" y="${(ty + 2.5).toFixed(1)}" class="sn">${i * 30}</text>`; }).join("");
    const pm = prev ? pt(ang(Number(prev.weight)), 58) : null;
    const diff = now && prev ? Math.round((W - Number(prev.weight)) * 10) / 10 : null;
    el.innerHTML = `
      <svg viewBox="0 0 240 262" class="scale-svg" id="scale-svg" role="img" aria-label="Weighing scale">
        <defs>
          <linearGradient id="sc-body" x1="0" y1="0" x2="0" y2="1"><stop offset="0" style="stop-color:var(--surface-alt)"/><stop offset="1" style="stop-color:var(--border)"/></linearGradient>
          <linearGradient id="sc-bezel" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#f4f4f6"/><stop offset=".5" stop-color="#8d8d95"/><stop offset="1" stop-color="#e6e6ea"/></linearGradient>
          <radialGradient id="sc-face" cx=".4" cy=".3" r=".9"><stop offset="0" style="stop-color:var(--surface)"/><stop offset="1" style="stop-color:var(--surface-alt)"/></radialGradient>
          <linearGradient id="sc-sheen" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#fff" stop-opacity=".28"/><stop offset=".45" stop-color="#fff" stop-opacity="0"/></linearGradient>
          <radialGradient id="sc-floor"><stop offset="0" stop-color="#000" stop-opacity=".4"/><stop offset="1" stop-color="#000" stop-opacity="0"/></radialGradient>
        </defs>
        <ellipse cx="120" cy="252" rx="98" ry="9" fill="url(#sc-floor)"/>
        <g id="scale-plate">
          <rect x="12" y="12" width="216" height="232" rx="46" fill="url(#sc-body)" class="s-body"/>
          <rect x="22" y="22" width="196" height="212" rx="36" class="s-glass"/>
          <path d="M40 22 H150 L22 150 V58 Q22 22 40 22Z" fill="url(#sc-sheen)"/>
          <circle cx="120" cy="92" r="68" fill="url(#sc-bezel)"/>
          <circle cx="120" cy="92" r="63" fill="url(#sc-face)" class="s-dial"/>
          <circle cx="120" cy="92" r="57" fill="none" class="s-track" stroke-width="4" stroke-linecap="round" stroke-dasharray="240 360" pathLength="360" transform="rotate(150 120 92)"/>
          <circle id="scale-arc" cx="120" cy="92" r="57" fill="none" stroke="var(--accent)" stroke-width="4" stroke-linecap="round" stroke-dasharray="0 360" pathLength="360" transform="rotate(150 120 92)"/>
          ${ticks}${nums}
          <text x="120" y="122" class="s-unit">KG</text>
          ${pm ? `<circle cx="${pm[0]}" cy="${pm[1]}" r="3" class="s-prev"><title>Last time</title></circle>` : ""}
          <g id="scale-needle" transform="rotate(${this._angle ?? -120} 120 92)" class="s-needle"><polygon points="118.6,98 120,42 121.4,98 120,110"/><circle cx="120" cy="92" r="6.5"/><circle cx="118.4" cy="90.4" r="2" fill="#fff" opacity=".7"/></g>
          <g class="s-feet"><path class="foot" d="M82 176c0-10 8-16 14-16s12 6 12 16-4 36-13 36-13-26-13-36z"/><path class="foot" d="M132 176c0-10 6-16 12-16s14 6 14 16-4 36-13 36-13-26-13-36z"/></g>
        </g>
      </svg>
      <div class="scale-read"><span class="scale-num" id="scale-num">${now ? (this._angle != null ? (((this._angle + 120) / 240) * MAX).toFixed(1) : "0.0") : "--"}</span><span class="scale-unit">kg</span></div>
      <div class="scale-meta">${now ? `Logged ${fmtDate(now.measured_at)}${diff !== null ? ` · <span class="delta ${diff > 0 ? "up" : diff < 0 ? "down" : ""}">${diff > 0 ? "▲" : diff < 0 ? "▼" : "•"} ${Math.abs(diff)} kg</span> since ${fmtDate(prev.measured_at)}` : ""}` : "Step on the scale to log your weight."}</div>
      <div class="scale-actions"><button class="btn btn-primary" id="step-on-btn">⚖ Step on the scale</button></div>
      <div id="weight-trend"></div>`;
    document.getElementById("step-on-btn").onclick = () => this.openMeasurementForm("m-weight");
    const weights = this.measurements.filter((m) => m.weight != null).map((m) => m.weight);
    if (weights.length > 1) renderLineTrend(document.getElementById("weight-trend"), weights);
    if (!now) return;

    const svg = document.getElementById("scale-svg"), plate = document.getElementById("scale-plate"), needle = document.getElementById("scale-needle"),
      arc = document.getElementById("scale-arc"), num = document.getElementById("scale-num");
    const target = ang(W);
    let pos = this._angle ?? -120, vel = 0;
    const paint = () => {
      needle.setAttribute("transform", `rotate(${pos.toFixed(2)} 120 92)`);
      arc.setAttribute("stroke-dasharray", `${Math.max(0, pos + 120).toFixed(2)} 360`);
      num.textContent = Math.max(0, ((pos + 120) / 240) * MAX).toFixed(1);
    };
    if (FX.reduced || Math.abs(target - pos) < 0.05) { pos = target; paint(); this._angle = target; return; }
    const spring = () => {
      svg.classList.add("stepping");
      let last = performance.now(); const t0 = last, k = 90, c = 12.5; // small overshoot, then settles
      const frame = (nowT) => {
        const dt = Math.min(0.032, (nowT - last) / 1000); last = nowT;
        const t = (nowT - t0) / 1000, a = target - pos;
        vel += (k * a - c * vel) * dt; pos += vel * dt;
        plate.setAttribute("transform", `translate(0 ${(4.5 * Math.exp(-4.5 * t) * Math.cos(15 * t)).toFixed(2)})`);
        paint();
        if (Math.abs(a) < 0.04 && Math.abs(vel) < 0.08 && t > 0.7) { pos = target; paint(); plate.removeAttribute("transform"); this._angle = target; return; }
        this._scaleRaf = requestAnimationFrame(frame);
      };
      this._scaleRaf = requestAnimationFrame(frame);
    };
    this._scaleTimer = setTimeout(spring, 260); // a short beat before the "step on"
  },


  // ---------- guided, one-part-at-a-time measuring ----------
  startWizard(steps) {
    const full = !steps;
    this.wiz = { steps: full ? ["shoulders", "chest", "arms", "waist", "thighs", "weight", "review"] : [...steps], i: 0, vals: {}, full, date: todayStr(), notes: "" };
    this.refreshWizard();
    document.getElementById("body-panel")?.scrollIntoView({ behavior: FX.reduced ? "auto" : "smooth", block: "nearest" });
  },

  async openMeasurementForm(focusId) {
    if (!document.getElementById("meas-wizard")) { this.activeTab = "measurements"; await this.render(); }
    const k = focusId && focusId.startsWith("m-") ? focusId.slice(2) : null;
    this.startWizard(k && (k === "weight" || BODY_PARTS.some((p) => p.key === k)) ? [k] : undefined);
  },

  gotoWizardPart(key) {
    const w = this.wiz, i = w.steps.indexOf(key);
    if (i < 0) return;
    this.readWizardInput();
    w.i = i;
    this.refreshWizard();
  },

  refreshWizard() {
    this.renderBodyMap();
    this.renderWizard();
    const key = this.wiz?.steps[this.wiz.i];
    document.getElementById("scale-panel")?.classList.toggle("ask", key === "weight");
    if (key === "weight" && this.wiz.vals.weight != null) this.tweenScale(this.wiz.vals.weight);
  },

  cancelWizard() {
    this.wiz = null;
    document.getElementById("scale-panel")?.classList.remove("ask");
    this.renderBodyMap();
    this.renderWizard();
    this.tweenScale(this.latestOf("weight").now ? Number(this.latestOf("weight").now.weight) : 0);
  },

  readWizardInput() {
    const w = this.wiz, inp = document.getElementById("wz-input");
    if (!w || !inp) return;
    const key = w.steps[w.i];
    if (inp.value === "") delete w.vals[key]; else w.vals[key] = Number(inp.value);
  },

  renderWizard() {
    const el = document.getElementById("meas-wizard");
    if (!el) return;
    const w = this.wiz;
    if (!w) { el.innerHTML = ""; return; }
    const key = w.steps[w.i], n = w.steps.length, isReview = key === "review", isLast = w.i === n - 1;
    const part = key === "weight" ? WEIGHT_STEP : BODY_PARTS.find((p) => p.key === key);
    const dots = `<div class="wiz-dots" aria-hidden="true">${w.steps.map((s, i) => `<i class="${i < w.i ? "done" : i === w.i ? "now" : ""}"></i>`).join("")}</div>`;

    if (isReview) {
      const rows = [...BODY_PARTS, WEIGHT_STEP].map((p) => `<button type="button" class="wiz-row" data-jump="${p.key}"><span>${p.label}</span><b>${w.vals[p.key] != null ? w.vals[p.key] + " " + p.unit : "skipped"}</b></button>`).join("");
      el.innerHTML = `<div class="wiz wiz-in">${dots}
        <div class="wiz-head"><span class="wiz-step">Review</span><button type="button" class="link-btn" id="wz-cancel">Cancel</button></div>
        <h4 class="wiz-title">All done — check and save</h4>
        <div class="wiz-rows">${rows}</div>
        <div class="wiz-meta"><label>Date<input type="date" id="wz-date" value="${w.date}" /></label><label>Notes<input type="text" id="wz-notes" placeholder="optional" value="${escapeHtml(w.notes)}" /></label></div>
        <div class="wiz-actions"><button type="button" class="btn btn-ghost" id="wz-back">Back</button><button type="button" class="btn btn-primary" id="wz-save">Save measurement</button></div></div>`;
      el.querySelectorAll("[data-jump]").forEach((b) => (b.onclick = () => { w.date = document.getElementById("wz-date").value || w.date; w.notes = document.getElementById("wz-notes").value; this.gotoWizardPart(b.dataset.jump); }));
      document.getElementById("wz-back").onclick = () => { w.i--; this.refreshWizard(); };
      document.getElementById("wz-cancel").onclick = () => this.cancelWizard();
      document.getElementById("wz-save").onclick = () => { w.date = document.getElementById("wz-date").value || todayStr(); w.notes = document.getElementById("wz-notes").value.trim(); this.saveWizard(); };
      return;
    }

    const last = this.latestOf(key).now?.[key];
    el.innerHTML = `<div class="wiz wiz-in">${dots}
      <div class="wiz-head"><span class="wiz-step">Step ${w.i + 1} of ${n}</span><button type="button" class="link-btn" id="wz-cancel">Cancel</button></div>
      <h4 class="wiz-title">${part.ask}</h4>
      <p class="wiz-hint">${part.hint}</p>
      <div class="wiz-input"><input type="number" id="wz-input" step="0.1" min="0" inputmode="decimal" autocomplete="off" placeholder="${last != null ? "last: " + last : "0.0"}" value="${w.vals[key] ?? ""}" /><span class="wiz-unit">${part.unit}</span></div>
      <div class="wiz-actions">
        <button type="button" class="btn btn-ghost" id="wz-back" ${w.i === 0 ? "disabled" : ""}>Back</button>
        <button type="button" class="btn btn-ghost" id="wz-skip">Skip</button>
        <button type="button" class="btn btn-primary" id="wz-next">${isLast ? "Save" : w.steps[w.i + 1] === "review" ? "Review" : "Next"}</button>
      </div></div>`;
    const inp = document.getElementById("wz-input");
    const go = (dir) => { this.readWizardInput(); w.i += dir; this.refreshWizard(); };
    const next = () => {
      if (inp.value === "" || Number(inp.value) <= 0) { inp.classList.remove("shake"); void inp.offsetWidth; inp.classList.add("shake"); return toast("Type a number, or press Skip.", "error"); }
      if (isLast) { this.readWizardInput(); this.saveWizard(); } else go(1);
    };
    document.getElementById("wz-next").onclick = next;
    document.getElementById("wz-skip").onclick = () => { delete w.vals[key]; if (isLast) { Object.keys(w.vals).length ? this.saveWizard() : this.cancelWizard(); } else { w.i++; this.refreshWizard(); } };
    document.getElementById("wz-back").onclick = () => go(-1);
    document.getElementById("wz-cancel").onclick = () => this.cancelWizard();
    inp.addEventListener("keydown", (e) => { if (e.key === "Enter") { e.preventDefault(); next(); } else if (e.key === "Escape") { e.stopPropagation(); this.cancelWizard(); } });
    if (key === "weight") inp.addEventListener("input", () => { const x = Number(inp.value); if (x >= 0) this.tweenScale(x); });
    else inp.addEventListener("input", () => { w.vals[key] = inp.value === "" ? undefined : Number(inp.value); const chip = document.querySelector(`.bchip-btn[data-part="${key}"] b`); if (chip) chip.textContent = inp.value === "" ? "+ add" : inp.value + " cm"; });
    setTimeout(() => inp.focus({ preventScroll: true }), 60);
  },

  async saveWizard() {
    const w = this.wiz;
    const row = { measured_at: w.date || todayStr(), notes: w.notes || "" };
    [...BODY_PARTS.map((p) => p.key), "weight"].forEach((k) => (row[k] = w.vals[k] != null && !Number.isNaN(w.vals[k]) ? w.vals[k] : null));
    if ([...BODY_PARTS.map((p) => p.key), "weight"].every((k) => row[k] == null)) return toast("Enter at least one measurement.", "error");
    await DB.insert("body_measurements", row);
    this.wiz = null;
    toast("Measurement saved.");
    this.renderMeasurements();
  },

  // eases the scale needle to a weight (used while typing in the weight step)
  tweenScale(wt) {
    const needle = document.getElementById("scale-needle"), arc = document.getElementById("scale-arc"), num = document.getElementById("scale-num");
    if (!needle) return;
    cancelAnimationFrame(this._scaleRaf); cancelAnimationFrame(this._twRaf); clearTimeout(this._scaleTimer);
    const MAX = 150, target = -120 + (Math.min(Math.max(wt, 0), MAX) / MAX) * 240;
    let pos = this._angle ?? -120;
    const paint = () => {
      needle.setAttribute("transform", `rotate(${pos.toFixed(2)} 120 92)`);
      arc.setAttribute("stroke-dasharray", `${Math.max(0, pos + 120).toFixed(2)} 360`);
      num.textContent = Math.max(0, ((pos + 120) / 240) * MAX).toFixed(1);
    };
    const step = () => {
      pos += (target - pos) * (FX.reduced ? 1 : 0.16);
      if (Math.abs(target - pos) < 0.05) pos = target;
      this._angle = pos; paint();
      if (pos !== target) this._twRaf = requestAnimationFrame(step);
    };
    step();
  },
};

const WEIGHT_STEP = { key: "weight", label: "Weight", unit: "kg", ask: "What do you weigh right now?", hint: "Step on the scale barefoot — mornings, before eating, give the most consistent reading." };

const WORKOUT_TYPES = [
  ["Split", ["Push", "Pull", "Legs", "Upper body", "Lower body", "Full body"]],
  ["Muscle group", ["Chest", "Back", "Shoulders", "Arms", "Core / Abs", "Glutes"]],
  ["Cardio", ["Running", "Walking", "Cycling", "Swimming", "HIIT", "Jump rope", "Cardio (general)"]],
  ["Other", ["Calisthenics", "Yoga", "Mobility / Stretching", "Sports", "Martial arts", "Other"]],
];

const BodyGender = {
  key: (uid) => `gender:${uid}`,
  async get(user) {
    let g = null; try { g = localStorage.getItem(this.key(user.id)); } catch {}
    if (!g) { try { const { data } = await DB.client.from("profiles").select("gender").eq("id", user.id).maybeSingle(); g = data?.gender || null; if (g) localStorage.setItem(this.key(user.id), g); } catch {} }
    return g === "male" || g === "female" ? g : null;
  },
  async set(user, g) { try { localStorage.setItem(this.key(user.id), g); } catch {} try { await DB.client.from("profiles").update({ gender: g }).eq("id", user.id); } catch {} },
};

const BODY_PARTS = [
  { key: "shoulders", label: "Shoulders", unit: "cm", ask: "Measure your shoulders", hint: "Stand tall and relaxed. Wrap the tape around the widest point of your shoulders, over the deltoids." },
  { key: "chest", label: "Chest", unit: "cm", ask: "Measure your chest", hint: "Wrap the tape under your armpits around the fullest part of your chest. Breathe out normally." },
  { key: "arms", label: "Arms", unit: "cm", ask: "Measure your upper arm", hint: "Around the thickest part of your upper arm. Keep it relaxed (or flexed) — just stay consistent." },
  { key: "waist", label: "Waist", unit: "cm", ask: "Measure your waist", hint: "At the narrowest point, usually just above the belly button. Don't suck in." },
  { key: "thighs", label: "Thighs", unit: "cm", ask: "Measure your thigh", hint: "Around the fullest part of your upper thigh, just below the glutes. Weight evenly on both feet." },
];

function numOrNullEl(input) {
  return input.value === "" ? null : Number(input.value);
}

// ---- js/skills.js ----
// ============================================================
// SKILLS — personal skill tracking (Java, Python, SQL, Power BI,
// Communication, or anything custom), current vs target level.
// ============================================================

const Skills = {
  list: [],

  async load() {
    const user = await DB.currentUser();
    this.list = await DB.list("skills", { filters: { user_id: user.id }, order: "created_at", ascending: true });
  },

  async render() {
    await this.load();
    const el = document.getElementById("page-skills");
    el.innerHTML = `
      <div class="page-header">
        <h2>Skills</h2>
        <button class="btn btn-primary" id="add-skill-btn">+ Add Skill</button>
      </div>
      <div id="skills-grid" class="subject-grid"></div>
    `;
    document.getElementById("add-skill-btn").onclick = () => this.openForm();
    this.renderGrid();
  },

  renderGrid() {
    const el = document.getElementById("skills-grid");
    if (!this.list.length) {
      el.innerHTML = `<p class="empty-state">No skills yet. Add one — Java, Python, SQL, Power BI, Communication, or anything custom.</p>`;
      return;
    }
    el.innerHTML = this.list
      .map((s) => {
        const pctVal = Math.min(100, Math.round((s.current_level / Math.max(1, s.target_level)) * 100));
        return `
        <div class="subject-card">
          <div class="subject-card-top"><h3>${escapeHtml(s.name)}</h3></div>
          <div class="bar-row" style="grid-template-columns:1fr 40px;">
            <div class="bar-track"><div class="bar-fill" style="width:${pctVal}%"></div></div>
            <span class="bar-value">${s.current_level}/${s.target_level}</span>
          </div>
          ${s.notes ? `<p class="subject-desc">${escapeHtml(s.notes)}</p>` : ""}
          <div class="subject-card-actions">
            <button class="link-btn" data-action="edit" data-id="${s.id}">Edit</button>
            <button class="link-btn danger" data-action="delete" data-id="${s.id}">Delete</button>
          </div>
        </div>`;
      })
      .join("");
    el.querySelectorAll("[data-action]").forEach((btn) => {
      btn.addEventListener("click", () => {
        const skill = this.list.find((s) => s.id === btn.dataset.id);
        if (btn.dataset.action === "edit") this.openForm(skill);
        else this.deleteFlow(skill);
      });
    });
  },

  openForm(skill = null) {
    openModal(`
      <h3>${skill ? "Edit Skill" : "Add Skill"}</h3>
      <form id="skill-form">
        <label>Skill name<input required id="sk-name" value="${skill ? escapeHtml(skill.name) : ""}" /></label>
        <label>Current level (1-10)<input type="number" min="1" max="10" id="sk-current" value="${skill?.current_level ?? 1}" /></label>
        <label>Target level (1-10)<input type="number" min="1" max="10" id="sk-target" value="${skill?.target_level ?? 10}" /></label>
        <label>Notes<textarea id="sk-notes">${skill ? escapeHtml(skill.notes || "") : ""}</textarea></label>
        <div class="modal-actions">
          <button type="button" class="btn btn-ghost" id="sk-cancel">Cancel</button>
          <button type="submit" class="btn btn-primary">Save</button>
        </div>
      </form>
    `);
    document.getElementById("sk-cancel").onclick = closeModal;
    document.getElementById("skill-form").onsubmit = async (e) => {
      e.preventDefault();
      const clamp = (v, d) => Math.min(10, Math.max(1, Math.round(Number(v) || d)));
      const payload = {
        name: document.getElementById("sk-name").value.trim(),
        current_level: clamp(document.getElementById("sk-current").value, 1),
        target_level: clamp(document.getElementById("sk-target").value, 10),
        notes: document.getElementById("sk-notes").value.trim(),
      };
      if (payload.current_level > payload.target_level) payload.target_level = payload.current_level;
      if (!payload.name) return;
      if (skill) await DB.update("skills", skill.id, payload);
      else await DB.insert("skills", payload);
      closeModal();
      toast(skill ? "Skill updated." : "Skill added.");
      this.render();
    };
  },

  async deleteFlow(skill) {
    const ok = await confirmDialog("Delete this skill?", "This can't be undone.", "Delete");
    if (!ok) return;
    await DB.remove("skills", skill.id);
    toast("Skill deleted.");
    this.render();
  },
};

// ---- js/calendar.js ----
// ============================================================
// CALENDAR — month grid. Clicking a date shows everything that
// happened or is due that day: tasks, study sessions, pomodoros,
// tests, workouts, milestone deadlines.
// All dates are the user's LOCAL calendar days.
// ============================================================

// What the person did each day shows up as little hanko-style stickers.
const STICKER_KEYS = ["study", "pomo", "task", "test", "workout", "mile"];
const STICKERS = {
  study:   { kj: "学", label: "Study",     cls: "stk-study" },
  pomo:    { kj: "時", label: "Pomodoro",  cls: "stk-pomo" },
  task:    { kj: "務", label: "Task done", cls: "stk-task" },
  test:    { kj: "試", label: "Test",      cls: "stk-test" },
  workout: { kj: "鍛", label: "Workout",   cls: "stk-workout" },
  mile:    { kj: "節", label: "Milestone", cls: "stk-mile" },
};

const Calendar = {
  viewDate: (() => { const d = new Date(); d.setDate(1); return d; })(),
  markedDates: new Set(),
  days: {},   // { "YYYY-MM-DD": { study: n, pomo: n, ..., xp: n, studySec: n } }

  shiftMonth(delta) {
    // always land on day 1 — setMonth() on the 31st used to skip whole months
    this.viewDate = new Date(this.viewDate.getFullYear(), this.viewDate.getMonth() + delta, 1);
    this.render();
  },

  async render() {
    const el = document.getElementById("page-calendar");
    const y = this.viewDate.getFullYear();
    const m = this.viewDate.getMonth();
    const monthLabel = this.viewDate.toLocaleDateString("en-IN", { month: "long", year: "numeric" });

    el.innerHTML = `
      <div class="page-header">
        <h2>Calendar</h2>
        <div class="header-actions">
          <button class="btn btn-ghost" id="cal-prev" aria-label="Previous month">‹</button>
          <span class="cal-month-label">${monthLabel}</span>
          <button class="btn btn-ghost" id="cal-next" aria-label="Next month">›</button>
          <button class="btn btn-ghost" id="cal-today">Today</button>
        </div>
      </div>
      <div class="cal-summary" id="cal-summary"></div>
      <div class="cal-board"><div class="cal-grid" id="cal-grid"></div></div>
      <div class="cal-legend" id="cal-legend">${Object.values(STICKERS).map((t) => `<span><i class="stk stk-xs ${t.cls}">${t.kj}</i>${t.label}</span>`).join("")}</div>
      <div id="cal-detail" class="panel hidden"></div>
    `;
    document.getElementById("cal-prev").onclick = () => this.shiftMonth(-1);
    document.getElementById("cal-next").onclick = () => this.shiftMonth(1);
    document.getElementById("cal-today").onclick = () => { const n = new Date(); this.viewDate = new Date(n.getFullYear(), n.getMonth(), 1); this.render(); };

    this.renderGrid(y, m); // grid first, dots fill in when the data arrives
    await this.loadMonthMarkers(y, m);
    if (document.getElementById("cal-grid")) { this.renderGrid(y, m); this.renderSummary(); }
  },

  renderSummary() {
    const el = document.getElementById("cal-summary");
    if (!el) return;
    const t = { xp: 0, active: 0, study: 0, workout: 0, task: 0, studySec: 0 };
    Object.values(this.days).forEach((d) => {
      t.xp += d.xp || 0; t.studySec += d.studySec || 0;
      t.study += (d.study || 0) + (d.pomo || 0); t.workout += d.workout || 0; t.task += d.task || 0;
      if (STICKER_KEYS.some((k) => d[k])) t.active++;
    });
    const cell = (kj, v, l) => `<div class="cal-sum"><span class="cal-sum-kj">${kj}</span><b>${v}</b><span>${l}</span></div>`;
    el.innerHTML = cell("日", t.active, "active days") + cell("経", t.xp.toLocaleString(), "XP earned") + cell("学", fmtDuration(t.studySec) || "0m", "studied") + cell("鍛", t.workout, "workouts") + cell("務", t.task, "tasks done");
  },

  async loadMonthMarkers(y, m) {
    const user = await DB.currentUser();
    const pad = (n) => String(n).padStart(2, "0");
    const startDate = `${y}-${pad(m + 1)}-01`;
    const endDate = localDateStr(new Date(y, m + 1, 0));
    const startTs = new Date(y, m, 1).toISOString();
    const endTs = new Date(y, m + 1, 1).toISOString();
    const days = {};
    const bump = (day, key, n = 1) => { if (!day) return; (days[day] = days[day] || {})[key] = (days[day][key] || 0) + n; };

    const [tasks, tests, workouts, milestones, sessions, pomos, xp] = await Promise.all([
      DB.client.from("tasks").select("due_date, status, completed_at").eq("user_id", user.id).or(`and(due_date.gte.${startDate},due_date.lte.${endDate}),and(completed_at.gte.${startTs},completed_at.lt.${endTs})`),
      DB.client.from("tests").select("test_date").eq("user_id", user.id).gte("test_date", startDate).lte("test_date", endDate),
      DB.client.from("workouts").select("workout_date").eq("user_id", user.id).gte("workout_date", startDate).lte("workout_date", endDate),
      DB.client.from("milestones").select("deadline, status").eq("user_id", user.id).gte("deadline", startDate).lte("deadline", endDate),
      DB.client.from("study_sessions").select("start_time, duration_sec").eq("user_id", user.id).gte("start_time", startTs).lt("start_time", endTs),
      DB.client.from("pomodoros").select("completed_at, duration_min").eq("user_id", user.id).gte("completed_at", startTs).lt("completed_at", endTs),
      DB.client.from("xp_events").select("amount, created_at").eq("user_id", user.id).gte("created_at", startTs).lt("created_at", endTs),
    ]);

    // a finished task is stamped on the day it was completed; an open one is only a "due" dot
    (tasks.data || []).forEach((t) => {
      if (t.status === "completed") bump(t.completed_at ? dayOf(t.completed_at) : t.due_date, "task");
      else if (t.due_date) bump(String(t.due_date).slice(0, 10), "due");
    });
    (tests.data || []).forEach((r) => bump(String(r.test_date).slice(0, 10), "test"));
    (workouts.data || []).forEach((r) => bump(String(r.workout_date).slice(0, 10), "workout"));
    (milestones.data || []).forEach((r) => bump(String(r.deadline).slice(0, 10), r.status === "completed" ? "mile" : "due"));
    (sessions.data || []).forEach((r) => { const d = dayOf(r.start_time); bump(d, "study"); bump(d, "studySec", r.duration_sec || 0); });
    (pomos.data || []).forEach((r) => bump(dayOf(r.completed_at), "pomo"));
    (xp.data || []).forEach((r) => bump(dayOf(r.created_at), "xp", r.amount || 0));

    this.days = days;
    this.markedDates = new Set(Object.keys(days));
  },

  renderGrid(y, m) {
    const grid = document.getElementById("cal-grid");
    if (!grid) return;
    const firstDay = new Date(y, m, 1).getDay();
    const daysInMonth = new Date(y, m + 1, 0).getDate();
    const today = todayStr();

    let cells = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"].map((d, i) => `<div class="cal-dow${i === 0 || i === 6 ? " we" : ""}">${d}</div>`).join("");
    for (let i = 0; i < firstDay; i++) cells += `<div class="cal-cell cal-empty"></div>`;
    for (let d = 1; d <= daysInMonth; d++) {
      const dateStr = `${y}-${String(m + 1).padStart(2, "0")}-${String(d).padStart(2, "0")}`;
      const isToday = dateStr === today, isFuture = dateStr > today;
      const info = this.days[dateStr] || {};
      const keys = STICKER_KEYS.filter((k) => info[k]);
      const shown = keys.slice(0, 4);
      const stickers = shown.map((k, i) => {
        const n = info[k], t = STICKERS[k];
        return `<i class="stk ${t.cls}" style="--r:${[-7, 5, -3, 8][i]}deg;--i:${i}" title="${t.label}${n > 1 ? " ×" + n : ""}">${t.kj}${n > 1 ? `<em>${n}</em>` : ""}</i>`;
      }).join("");
      const perfect = keys.length >= 3;
      cells += `<button type="button" class="cal-cell${isToday ? " cal-today" : ""}${keys.length ? " has" : ""}${isFuture ? " future" : ""}${perfect ? " perfect" : ""}" data-date="${dateStr}" style="--cd:${(d % 7) * 40 + Math.floor(d / 7) * 30}ms" aria-label="${fmtDate(dateStr)}${keys.length ? ", " + keys.map((k) => STICKERS[k].label).join(", ") : ""}">
        <span class="cal-num">${d}</span>
        ${info.xp ? `<span class="cal-xp">+${info.xp}</span>` : ""}
        <span class="cal-stk">${stickers}</span>
        ${info.due && !isFuture ? "" : ""}${info.due ? '<span class="cal-dot" title="Something is due"></span>' : ""}
      </button>`;
    }
    grid.innerHTML = cells;
    grid.querySelectorAll(".cal-cell[data-date]").forEach((cell) => {
      cell.addEventListener("click", () => this.renderDetail(cell.dataset.date));
    });
  },

  async renderDetail(dateStr) {
    const detailEl = document.getElementById("cal-detail");
    detailEl.classList.remove("hidden");
    detailEl.innerHTML = `<p class="empty-state">Loading...</p>`;
    detailEl.scrollIntoView({ behavior: "smooth", block: "nearest" });

    const user = await DB.currentUser();
    const { start, end } = dayBounds(dateStr);
    const [tasks, tests, workouts, milestones, sessions, pomos] = await Promise.all([
      DB.client.from("tasks").select("*").eq("user_id", user.id).eq("due_date", dateStr),
      DB.client.from("tests").select("*").eq("user_id", user.id).eq("test_date", dateStr),
      DB.client.from("workouts").select("*").eq("user_id", user.id).eq("workout_date", dateStr),
      DB.client.from("milestones").select("*").eq("user_id", user.id).eq("deadline", dateStr),
      DB.client.from("study_sessions").select("*").eq("user_id", user.id).gte("start_time", start).lt("start_time", end),
      DB.client.from("pomodoros").select("*").eq("user_id", user.id).gte("completed_at", start).lt("completed_at", end),
    ]);

    const section = (title, rows, render) =>
      rows.length ? `<h4 class="admin-section-title">${title}</h4>${rows.map(render).join("")}` : "";

    const parts = [
      section("Tasks", tasks.data || [], (t) => `<div class="mini-row"><span>${t.status === "completed" ? "✅" : "⬜"} ${escapeHtml(t.title)}</span><span class="muted">${escapeHtml(t.category || "")}</span></div>`),
      section("Tests", tests.data || [], (t) => `<div class="mini-row"><span>${escapeHtml(t.name)}</span><span>${t.total_marks ? pct(t.marks_obtained, t.total_marks) + "%" : "—"}</span></div>`),
      section("Study Sessions", sessions.data || [], (s) => `<div class="mini-row"><span>${escapeHtml(s.topic_text || "Study session")}</span><span>${fmtDuration(s.duration_sec)}</span><button class=\"rec-del\" type=\"button\" data-del-kind=\"session\" data-del-id=\"${s.id}\" title=\"Delete (asks for your password)\" aria-label=\"Delete this session\">🗑</button></div>`),
      section("Pomodoros", pomos.data || [], (p) => `<div class="mini-row"><span>${escapeHtml(p.topic_text || "Pomodoro")}</span><span>${p.duration_min} min</span></div>`),
      section("Workouts", workouts.data || [], (w) => `<div class="mini-row"><span>${escapeHtml(w.workout_type || "Workout")}</span></div>`),
      section("Milestone Deadlines", milestones.data || [], (g) => `<div class="mini-row"><span>${escapeHtml(g.title)}</span><span>${g.progress}%</span></div>`),
    ].filter(Boolean);

    const info = this.days[dateStr] || {};
    const row = STICKER_KEYS.filter((k) => info[k]).map((k) => `<span class="stk ${STICKERS[k].cls}" title="${STICKERS[k].label}">${STICKERS[k].kj}</span>`).join("");
    detailEl.innerHTML = `<div class="cal-detail-head"><h3>${fmtDate(dateStr)}</h3><div class="cal-detail-stk">${row}${info.xp ? `<b class="cal-detail-xp">+${info.xp} XP</b>` : ""}</div></div>${parts.length ? parts.join("") : `<p class="empty-state">Nothing recorded for this day.</p>`}`;
  },
};

// ---- js/history.js ----
// ============================================================
// HISTORY — unified view. Works across whatever goals the user
// has created.
// ============================================================

const History = {
  activeTab: "tests",

  async render() {
    const el = document.getElementById("page-history");
    el.innerHTML = `
      <div class="page-header"><h2>History</h2></div>
      <div class="tabs" id="history-tabs">
        <button class="tab active" data-tab="tests">Tests</button>
        <button class="tab" data-tab="all">All Activity</button>
      </div>
      <div class="search-row">
        <input id="history-search" placeholder="Search history..." />
      </div>
      <div id="history-body"></div>
    `;
    document.querySelectorAll("#history-tabs .tab").forEach((t) => {
      t.onclick = () => {
        document.querySelectorAll("#history-tabs .tab").forEach((x) => x.classList.remove("active"));
        t.classList.add("active");
        this.activeTab = t.dataset.tab;
        this.renderBody();
      };
    });
    this.cache = {};
    let t = null;
    document.getElementById("history-search").oninput = () => { clearTimeout(t); t = setTimeout(() => this.renderBody(), 150); };
    this.renderBody();
  },

  async renderBody() {
    const body = document.getElementById("history-body");
    const query = document.getElementById("history-search").value.toLowerCase();
    const user = await DB.currentUser();
    if (!user) return;

    if (this.activeTab === "tests") {
      if (!this.cache.tests) { await Promise.all([Tests.load(), Goals.load()]); this.cache.tests = true; }
      const filtered = Tests.list.filter((t) => t.name.toLowerCase().includes(query));
      if (!filtered.length) {
        body.innerHTML = `<p class="empty-state">No matching test records.</p>`;
        return;
      }
      body.innerHTML = filtered
        .map((t) => {
          const subject = Goals.subjects.find((s) => s.id === t.subject_id);
          const goal = Goals.list.find((g) => g.id === t.goal_id);
          const percentage = t.total_marks ? pct(t.marks_obtained, t.total_marks) : "—";
          return `<div class="record-card">
            <div class="record-main">
              <strong>${escapeHtml(t.name)}</strong>
              <span class="muted">${escapeHtml(goal?.name || "")}${subject ? " · " + escapeHtml(subject.name) : ""} · ${fmtDate(t.test_date)}</span>
            </div>
            <div class="record-stats"><span>${percentage}${percentage !== "—" ? "%" : ""}</span></div>
          </div>`;
        })
        .join("");
      return;
    }

    if (!this.cache.activity) {
      this.cache.activity = await DB.list("activity_log", {
        filters: { user_id: user.id },
        order: "occurred_at",
        ascending: false,
        limit: 300,
      });
    }
    const activity = this.cache.activity;
    const filtered = activity.filter((a) => a.description.toLowerCase().includes(query));
    if (!filtered.length) {
      body.innerHTML = `<p class="empty-state">No activity yet.</p>`;
      return;
    }
    body.innerHTML = filtered
      .map(
        (a) => `<div class="activity-row">
          <span class="activity-dot activity-${a.activity_type}"></span>
          <span>${escapeHtml(a.description)}</span>
          <span class="muted">${fmtDate(a.occurred_at)}</span>
        </div>`
      )
      .join("");
  },
};

// ---- js/analysis.js ----
// ============================================================
// ANALYSIS — one tab per goal the user has created, each with
// overall average, subject breakdown, best/worst, and a score
// progression chart. Works identically for JEE, NEET, CLAT,
// College, Boards, or any custom goal.
// ============================================================

const Analysis = {
  activeGoalId: null,

  async render() {
    await Goals.load();
    await Tests.load();
    const el = document.getElementById("page-analysis");
    const activeGoals = Goals.list.filter((g) => !g.archived);

    if (!activeGoals.length) {
      el.innerHTML = `<div class="page-header"><h2>Analysis</h2></div><p class="empty-state">Add a goal and a few tests to see analysis here.</p>`;
      return;
    }
    if (!this.activeGoalId) this.activeGoalId = activeGoals[0].id;

    el.innerHTML = `
      <div class="page-header"><h2>Analysis</h2></div>
      <div class="tabs" id="analysis-tabs">
        ${activeGoals.map((g) => `<button class="tab ${g.id === this.activeGoalId ? "active" : ""}" data-goal="${g.id}">${escapeHtml(g.name)}</button>`).join("")}
      </div>
      <div id="analysis-body"></div>
    `;
    document.querySelectorAll("#analysis-tabs .tab").forEach((t) => {
      t.onclick = () => {
        this.activeGoalId = t.dataset.goal;
        this.render();
      };
    });
    this.renderGoalAnalysis(this.activeGoalId);
  },

  renderGoalAnalysis(goalId) {
    const body = document.getElementById("analysis-body");
    const tests = Tests.list.filter((t) => t.goal_id === goalId && t.total_marks);

    if (!tests.length) {
      body.innerHTML = `<p class="empty-state">Complete more tests under this goal to generate a trend.</p>`;
      return;
    }

    const scores = tests.map((t) => pct(t.marks_obtained, t.total_marks));
    const overallAvg = Math.round(avg(scores));

    const bySubject = {};
    tests.forEach((t) => {
      const key = t.subject_id || "none";
      bySubject[key] = bySubject[key] || [];
      bySubject[key].push(pct(t.marks_obtained, t.total_marks));
    });
    const subjectLabels = Object.keys(bySubject).map(
      (id) => Goals.subjects.find((s) => s.id === id)?.name || "Unassigned"
    );
    const subjectAverages = Object.values(bySubject).map((arr) => Math.round(avg(arr)));

    const best = tests.reduce((a, b) => (pct(a.marks_obtained, a.total_marks) > pct(b.marks_obtained, b.total_marks) ? a : b));
    const worst = tests.reduce((a, b) => (pct(a.marks_obtained, a.total_marks) < pct(b.marks_obtained, b.total_marks) ? a : b));

    body.innerHTML = `
      <div class="stat-cards">
        <div class="stat-card"><span class="stat-label">Overall Average</span><span class="stat-value">${overallAvg}%</span></div>
        <div class="stat-card"><span class="stat-label">Tests Recorded</span><span class="stat-value">${tests.length}</span></div>
        <div class="stat-card"><span class="stat-label">Best Recorded</span><span class="stat-value">${pct(best.marks_obtained, best.total_marks)}%</span><span class="stat-sub">${escapeHtml(best.name)}</span></div>
        <div class="stat-card"><span class="stat-label">Lowest Recorded</span><span class="stat-value">${pct(worst.marks_obtained, worst.total_marks)}%</span><span class="stat-sub">${escapeHtml(worst.name)}</span></div>
      </div>
      <div class="panel">
        <h3>Average by Subject</h3>
        <div id="subject-bar-chart"></div>
      </div>
      <div class="panel">
        <h3>Score Progression (chronological)</h3>
        <div id="score-trend"></div>
      </div>
    `;
    renderBarChart(document.getElementById("subject-bar-chart"), subjectLabels, subjectAverages, { formatter: (v) => v + "%" });
    const chronological = [...tests].sort((a, b) => new Date(a.test_date) - new Date(b.test_date));
    renderLineTrend(document.getElementById("score-trend"), chronological.map((t) => pct(t.marks_obtained, t.total_marks)));
  },
};

